    ('Kua Poojan', 5, 18, true), ('Proposal Ceremony', 12, 19, true), ('Religious', 10, 20, true),
    ('Mata Ki Chowki', 36, 21, true), ('Lohri', 33, 22, true), ('Diwali Party', 34, 23, true),
