-- >>>>>>>>>> 0003_profiles_auth.sql
-- =============================================================================
-- 0003_profiles_auth.sql — profiles, phone login, account creation helpers.
--
-- Login = 10-digit phone + password. Supabase Auth's phone provider needs an SMS
-- provider, so the phone is mapped to an internal email `<phone>@phone.invalid`
-- (never shown in the UI). RLS relies on auth.uid(), so we must use Supabase Auth.
--
-- Accounts are invite-only: the owner runs, in the SQL Editor,
--     select public.create_app_user('9876543210', 'Full Name');
-- which creates the login with the default password; the user must change it
-- on first login (profiles.must_change_password).
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Phone helpers ---------------------------------------------------
-- Keeps the last 10 digits after stripping +91 / 0 / spaces / dashes.
create or replace function public.normalize_phone(p_phone text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when d ~ '^[6-9][0-9]{9}$' then d
    when d ~ '^91[6-9][0-9]{9}$' then substr(d, 3)
    when d ~ '^0[6-9][0-9]{9}$' then substr(d, 2)
    else null
  end
  from (select regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') as d) s;
$$;

create or replace function public.phone_login_email(p_phone text)
returns text
language sql
immutable
set search_path = ''
as $$
  select public.normalize_phone(p_phone) || '@phone.invalid';
$$;

-- ---------- Profiles --------------------------------------------------------
create table if not exists public.profiles (
  id                   uuid primary key references auth.users (id) on delete cascade,
  phone                text unique check (phone ~ '^[6-9][0-9]{9}$'),
  full_name            text check (full_name is null or length(full_name) <= 120),
  business_name        text check (business_name is null or length(business_name) <= 120),
  logo_path            text,
  contact_line         text check (contact_line is null or length(contact_line) <= 200),
  lms_logged_user_id   text check (lms_logged_user_id is null or lms_logged_user_id ~ '^[0-9]{1,10}$'),
  must_change_password boolean not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

drop trigger if exists set_updated_at on public.profiles;
create trigger set_updated_at before update on public.profiles
  for each row execute function public.set_updated_at();

-- ---------- New auth user -> profile + own option lists ----------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text;
begin
  v_phone := coalesce(
    public.normalize_phone(new.phone),
    case when new.email ilike '%@phone.invalid' then public.normalize_phone(split_part(new.email, '@', 1)) end
  );

  insert into public.profiles (id, phone, full_name, must_change_password)
  values (new.id, v_phone, nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''), true)
  on conflict (id) do nothing;

  perform public.seed_default_options(new.id);
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------- Owner-only account helpers (SQL Editor only) ---------------------
create or replace function public.create_app_user(
  p_phone     text,
  p_full_name text,
  p_password  text default 'ambria@123'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text := public.normalize_phone(p_phone);
  v_email text;
  v_id    uuid := gen_random_uuid();
begin
  if v_phone is null then
    raise exception 'Invalid phone number: %. Use a 10-digit Indian mobile number.', p_phone;
  end if;
  if length(coalesce(p_password, '')) < 6 then
    raise exception 'Password must be at least 6 characters (Supabase minimum).';
  end if;

  v_email := v_phone || '@phone.invalid';
  if exists (select 1 from auth.users where email = v_email) then
    raise exception 'A user with phone % already exists.', v_phone;
  end if;

  -- Token columns must be '' (not NULL) or Supabase Auth fails to sign the user in.
  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change
  ) values (
    '00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email,
    extensions.crypt(p_password, extensions.gen_salt('bf')), now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('full_name', p_full_name, 'phone', v_phone),
    now(), now(), '', '', '', ''
  );

  insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (
    gen_random_uuid(), v_id, v_id::text,
    jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true),
    'email', now(), now(), now()
  );

  return v_id;
end;
$$;

-- Owner resets a forgotten password back to the default; user must change it again.
create or replace function public.reset_user_password(p_phone text, p_password text default 'ambria@123')
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if length(coalesce(p_password, '')) < 6 then
    raise exception 'Password must be at least 6 characters (Supabase minimum).';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
         updated_at = now()
   where email = public.phone_login_email(p_phone)
  returning id into v_id;

  if v_id is null then
    raise exception 'No user with phone %', p_phone;
  end if;

  update public.profiles set must_change_password = true where id = v_id;
end;
$$;

revoke all on function public.create_app_user(text, text, text) from public, anon, authenticated;
revoke all on function public.reset_user_password(text, text) from public, anon, authenticated;
revoke all on function public.handle_new_user() from public, anon, authenticated;

-- ---------- Called by the app after a successful password change ------------
create or replace function public.mark_password_changed()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  update public.profiles set must_change_password = false where id = auth.uid();
end;
$$;

revoke all on function public.mark_password_changed() from public, anon;
grant execute on function public.mark_password_changed() to authenticated;
grant execute on function public.normalize_phone(text) to anon, authenticated;
grant execute on function public.phone_login_email(text) to anon, authenticated;

-- >>>>>>>>>> 0004_catalogue.sql
-- =============================================================================
-- 0004_catalogue.sql — elements, packages, package-element mapping, vendors,
-- vendor purchase rates. All per user (owner_id); composite FKs stop a row from
-- pointing at another user's data.
-- Packages deliberately have NO function column — packages are function-independent.
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Elements --------------------------------------------------------
create table if not exists public.elements (
  id           uuid primary key default gen_random_uuid(),
  owner_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name         text not null check (length(btrim(name)) between 1 and 120),
  unit         text check (unit is null or length(unit) <= 30),
  default_rate numeric(12, 2) not null check (default_rate >= 0),
  default_qty  numeric(10, 2) check (default_qty is null or default_qty > 0),
  image_path   text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (owner_id, id)
);
-- Name unique among a user's active elements (archived ones may repeat).
create unique index if not exists elements_owner_active_name_uq
  on public.elements (owner_id, lower(name)) where is_active;
create index if not exists elements_owner_active_name_idx on public.elements (owner_id, is_active, name);
create index if not exists elements_name_trgm_idx on public.elements using gin (name extensions.gin_trgm_ops);

-- ---------- Packages --------------------------------------------------------
create table if not exists public.packages (
  id            uuid primary key default gen_random_uuid(),
  owner_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name          text not null check (length(btrim(name)) between 1 and 120),
  tier_id       uuid not null,
  display_price numeric(12, 2) check (display_price is null or display_price >= 0),
  description   text check (description is null or length(description) <= 1000),
  image_path    text,
  video_url     text check (video_url is null or video_url ~* '^https?://[^\s]+$'),
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (owner_id, id),
  foreign key (owner_id, tier_id) references public.tiers (owner_id, id)
);
create unique index if not exists packages_owner_active_name_tier_uq
  on public.packages (owner_id, lower(name), tier_id) where is_active;
create index if not exists packages_owner_active_idx on public.packages (owner_id, is_active, name);

-- ---------- Package ↔ element mapping --------------------------------------
create table if not exists public.package_elements (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  package_id  uuid not null,
  element_id  uuid not null,
  default_qty numeric(10, 2) not null default 1 check (default_qty > 0),
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (package_id, element_id),
  foreign key (owner_id, package_id) references public.packages (owner_id, id) on delete cascade,
  foreign key (owner_id, element_id) references public.elements (owner_id, id)
);
create index if not exists package_elements_owner_package_idx on public.package_elements (owner_id, package_id, sort_order);
create index if not exists package_elements_element_idx on public.package_elements (owner_id, element_id);

-- ---------- Vendors ---------------------------------------------------------
create table if not exists public.vendors (
  id             uuid primary key default gen_random_uuid(),
  owner_id       uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name           text not null check (length(btrim(name)) between 1 and 120),
  contact_person text check (contact_person is null or length(contact_person) <= 120),
  phone          text check (phone is null or length(phone) <= 20),
  notes          text check (notes is null or length(notes) <= 1000),
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (owner_id, id)
);
create unique index if not exists vendors_owner_active_name_uq
  on public.vendors (owner_id, lower(name)) where is_active;

-- ---------- Vendor purchase rates (append-only; correct by voiding) ----------
create table if not exists public.vendor_rate_entries (
  id            uuid primary key default gen_random_uuid(),
  owner_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  element_id    uuid not null,
  vendor_id     uuid not null,
  purchase_date date not null,
  qty           numeric(10, 3) not null check (qty > 0),
  unit          text check (unit is null or length(unit) <= 30),
  rate_per_unit numeric(12, 2) not null check (rate_per_unit >= 0),
  remarks       text check (remarks is null or length(remarks) <= 500),
  logged_by     uuid not null default auth.uid() references auth.users (id),
  logged_at     timestamptz not null default now(),
  voided_at     timestamptz,
  void_reason   text,
  check ((voided_at is null) = (void_reason is null)),
  check (purchase_date <= (logged_at at time zone 'Asia/Kolkata')::date),
  unique (owner_id, id),
  foreign key (owner_id, element_id) references public.elements (owner_id, id),
  foreign key (owner_id, vendor_id) references public.vendors (owner_id, id)
);
-- Keyset pagination + trend lookups: latest entries per element by purchase date.
create index if not exists vendor_rates_owner_element_date_idx
  on public.vendor_rate_entries (owner_id, element_id, purchase_date desc, logged_at desc, id);
create index if not exists vendor_rates_owner_logged_idx
  on public.vendor_rate_entries (owner_id, logged_at desc, id);

-- Void instead of edit/delete. The only way to change an entry.
create or replace function public.void_vendor_rate_entry(p_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A reason is required to void an entry.';
  end if;
  update public.vendor_rate_entries
     set voided_at = now(), void_reason = btrim(p_reason)
   where id = p_id and owner_id = auth.uid() and voided_at is null;
  if not found then
    raise exception 'Entry not found or already voided.';
  end if;
end;
$$;
revoke all on function public.void_vendor_rate_entry(uuid, text) from public, anon;
grant execute on function public.void_vendor_rate_entry(uuid, text) to authenticated;

-- updated_at triggers
do $$
declare t text;
begin
  foreach t in array array['elements', 'packages', 'package_elements', 'vendors'] loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format('create trigger set_updated_at before update on public.%I
                    for each row execute function public.set_updated_at()', t);
  end loop;
end $$;

-- >>>>>>>>>> 0005_quotes_ledger.sql
-- =============================================================================
-- 0005_quotes_ledger.sql — quotes (with snapshots), items, charges, per-user
-- quote numbers, rate change history, audit log.
--
-- Snapshots: quotes copy names/rates at save time, so later edits to elements,
-- packages or options never change a saved quote.
-- Once a quote leaves 'draft', its items, charges and amounts are frozen.
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Per-user quote numbers: ENT-2026-00001 --------------------------
create table if not exists public.quote_counters (
  owner_id uuid    not null default auth.uid() references auth.users (id) on delete cascade,
  year     integer not null,
  last_no  integer not null default 0,
  primary key (owner_id, year)
);

create or replace function public.next_quote_no()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid  uuid := auth.uid();
  v_year integer := extract(year from (now() at time zone 'Asia/Kolkata'))::integer;
  v_no   integer;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  insert into public.quote_counters as c (owner_id, year, last_no)
  values (v_uid, v_year, 1)
  on conflict (owner_id, year) do update set last_no = c.last_no + 1
  returning last_no into v_no;
  return format('ENT-%s-%s', v_year, lpad(v_no::text, 5, '0'));
end;
$$;
revoke all on function public.next_quote_no() from public, anon, authenticated;

-- ---------- Quotes ----------------------------------------------------------
create table if not exists public.quotes (
  id                uuid primary key default gen_random_uuid(),
  owner_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  quote_no          text not null,
  status            public.quote_status not null default 'draft',
  source            public.quote_source not null default 'manual',
  source_ref        text,
  source_raw        jsonb,
  -- guest / event snapshot
  guest_name        text not null check (length(btrim(guest_name)) between 1 and 120),
  guest_phone       text check (guest_phone is null or guest_phone ~ '^[6-9][0-9]{9}$'),
  venue_name        text,
  sub_venue_name    text,
  event_date        date,
  session_name      text,
  function_name     text not null check (length(btrim(function_name)) between 1 and 80),
  -- package snapshot
  package_id        uuid,
  package_name      text,
  package_tier      text,
  -- totals (recomputed server-side on save)
  elements_subtotal numeric(14, 2) not null default 0 check (elements_subtotal >= 0),
  charges_total     numeric(14, 2) not null default 0 check (charges_total >= 0),
  final_total       numeric(14, 2) not null default 0 check (final_total >= 0),
  notes             text check (notes is null or length(notes) <= 2000),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (final_total = elements_subtotal + charges_total),
  unique (owner_id, id),
  unique (owner_id, quote_no),
  foreign key (owner_id, package_id) references public.packages (owner_id, id)
);
create index if not exists quotes_owner_created_idx on public.quotes (owner_id, created_at desc, id);
create index if not exists quotes_owner_status_idx on public.quotes (owner_id, status, created_at desc);
create index if not exists quotes_owner_function_idx on public.quotes (owner_id, function_name);
create index if not exists quotes_owner_package_idx on public.quotes (owner_id, package_id);
create index if not exists quotes_owner_event_date_idx on public.quotes (owner_id, event_date);
create index if not exists quotes_guest_trgm_idx on public.quotes using gin (guest_name extensions.gin_trgm_ops);
create index if not exists quotes_phone_idx on public.quotes (owner_id, guest_phone);

-- ---------- Quote items (snapshot of each element line) ---------------------
create table if not exists public.quote_items (
  id                   uuid primary key default gen_random_uuid(),
  owner_id             uuid not null default auth.uid() references auth.users (id) on delete cascade,
  quote_id             uuid not null,
  element_id           uuid,
  element_name         text not null check (length(btrim(element_name)) between 1 and 120),
  unit                 text,
  image_path           text,
  master_rate_at_quote numeric(12, 2) check (master_rate_at_quote is null or master_rate_at_quote >= 0),
  qty                  numeric(10, 2) not null check (qty > 0),
  rate                 numeric(12, 2) not null check (rate >= 0),
  amount               numeric(14, 2) not null check (amount >= 0),
  is_included          boolean not null default true,
  unit_cost_at_quote   numeric(12, 2) check (unit_cost_at_quote is null or unit_cost_at_quote >= 0),
  sort_order           integer not null default 0,
  created_at           timestamptz not null default now(),
  check (amount = round(qty * rate, 2)),
  foreign key (owner_id, quote_id) references public.quotes (owner_id, id),
  foreign key (owner_id, element_id) references public.elements (owner_id, id)
);
create index if not exists quote_items_owner_quote_idx on public.quote_items (owner_id, quote_id, sort_order);
create index if not exists quote_items_element_idx on public.quote_items (owner_id, element_id);

-- ---------- Additional charges ---------------------------------------------
create table if not exists public.quote_charges (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  quote_id    uuid not null,
  description text not null check (length(btrim(description)) between 1 and 200),
  amount      numeric(14, 2) not null check (amount >= 0),
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  foreign key (owner_id, quote_id) references public.quotes (owner_id, id)
);
create index if not exists quote_charges_owner_quote_idx on public.quote_charges (owner_id, quote_id, sort_order);

-- ---------- Rate change history (append-only) -------------------------------
create table if not exists public.rate_change_logs (
  id           uuid primary key default gen_random_uuid(),
  owner_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  change_type  public.rate_change_type not null,
  element_id   uuid,
  element_name text not null,
  package_id   uuid,
  quote_id     uuid,
  old_rate     numeric(12, 2) check (old_rate is null or old_rate >= 0),
  new_rate     numeric(12, 2) not null check (new_rate >= 0),
  reason       text check (reason is null or length(reason) <= 500),
  changed_by   uuid not null default auth.uid() references auth.users (id),
  changed_at   timestamptz not null default now(),
  check (change_type <> 'quote_override' or quote_id is not null),
  foreign key (owner_id, element_id) references public.elements (owner_id, id),
  foreign key (owner_id, package_id) references public.packages (owner_id, id),
  foreign key (owner_id, quote_id) references public.quotes (owner_id, id)
);
create index if not exists rate_logs_owner_changed_idx on public.rate_change_logs (owner_id, changed_at desc, id);
create index if not exists rate_logs_owner_element_idx on public.rate_change_logs (owner_id, element_id, changed_at desc);
create index if not exists rate_logs_owner_type_idx on public.rate_change_logs (owner_id, change_type, changed_at desc);

-- ---------- Audit log (append-only, written by triggers) --------------------
create table if not exists public.audit_log (
  id         uuid primary key default gen_random_uuid(),
  owner_id   uuid not null references auth.users (id) on delete cascade,
  table_name text not null,
  row_id     uuid not null,
  action     text not null,
  old_data   jsonb,
  new_data   jsonb,
  actor      uuid default auth.uid(),
  at         timestamptz not null default now()
);
create index if not exists audit_owner_at_idx on public.audit_log (owner_id, at desc, id);
create index if not exists audit_owner_row_idx on public.audit_log (owner_id, table_name, row_id);

-- ---------- Triggers --------------------------------------------------------
-- Quote number is always server-generated.
create or replace function public.quotes_before_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.quote_no := public.next_quote_no();
  new.status := 'draft';
  return new;
end;
$$;
drop trigger if exists quotes_before_insert on public.quotes;
create trigger quotes_before_insert before insert on public.quotes
  for each row execute function public.quotes_before_insert();

-- After a quote leaves draft only status/notes may change; status moves forward only.
create or replace function public.quotes_before_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id <> old.owner_id or new.quote_no <> old.quote_no then
    raise exception 'owner and quote number cannot change';
  end if;

  if old.status <> 'draft' then
    if (to_jsonb(new) - array['status', 'notes', 'updated_at'])
       <> (to_jsonb(old) - array['status', 'notes', 'updated_at']) then
      raise exception 'Quote % is % and can no longer be edited.', old.quote_no, old.status;
    end if;
  end if;

  if new.status <> old.status and not (
       (old.status = 'draft' and new.status in ('sent', 'confirmed', 'cancelled'))
    or (old.status = 'sent' and new.status in ('confirmed', 'cancelled'))
    or (old.status = 'confirmed' and new.status = 'cancelled')
  ) then
    raise exception 'Invalid status change: % -> %', old.status, new.status;
  end if;

  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists quotes_before_update on public.quotes;
create trigger quotes_before_update before update on public.quotes
  for each row execute function public.quotes_before_update();

-- Status changes go to the audit log.
create or replace function public.quotes_audit_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is distinct from old.status then
    insert into public.audit_log (owner_id, table_name, row_id, action, old_data, new_data)
    values (new.owner_id, 'quotes', new.id, 'status_change',
            jsonb_build_object('status', old.status), jsonb_build_object('status', new.status));
  end if;
  return new;
end;
$$;
drop trigger if exists quotes_audit_status on public.quotes;
create trigger quotes_audit_status after update on public.quotes
  for each row execute function public.quotes_audit_status();

-- Items and charges can only change while the parent quote is a draft.
create or replace function public.quote_children_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_status public.quote_status;
  v_quote  uuid := coalesce(new.quote_id, old.quote_id);
begin
  select status into v_status from public.quotes where id = v_quote;
  if v_status is not null and v_status <> 'draft' then
    raise exception 'Quote is % — its lines are frozen.', v_status;
  end if;
  return coalesce(new, old);
end;
$$;
drop trigger if exists quote_items_guard on public.quote_items;
create trigger quote_items_guard before insert or update or delete on public.quote_items
  for each row execute function public.quote_children_guard();
drop trigger if exists quote_charges_guard on public.quote_charges;
create trigger quote_charges_guard before insert or update or delete on public.quote_charges
  for each row execute function public.quote_children_guard();

revoke all on function public.quotes_before_insert() from public, anon, authenticated;
revoke all on function public.quotes_audit_status() from public, anon, authenticated;

-- >>>>>>>>>> 0006_rls.sql
-- =============================================================================
-- 0006_rls.sql — Row Level Security + grants. Every user sees and changes only
-- their own rows (owner_id = auth.uid()). anon gets nothing.
--
-- No DELETE on history tables (quotes, vendor rates, rate logs, audit) — history
-- is permanent. Elements/packages/options are archived via is_active instead.
-- `(select auth.uid())` is used so Postgres evaluates it once per query.
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Helper: (re)create the standard owner policies ------------------
create or replace function public._apply_owner_policies(p_table text, p_ops text[])
returns void
language plpgsql
set search_path = ''
as $$
declare
  op text;
begin
  execute format('alter table public.%I enable row level security', p_table);
  execute format('revoke all on public.%I from anon, authenticated', p_table);

  foreach op in array array['select', 'insert', 'update', 'delete'] loop
    execute format('drop policy if exists %I on public.%I', 'own_' || op, p_table);
  end loop;

  foreach op in array p_ops loop
    execute format('grant %s on public.%I to authenticated', op, p_table);
    if op = 'select' or op = 'delete' then
      execute format(
        'create policy %I on public.%I for %s to authenticated using (owner_id = (select auth.uid()))',
        'own_' || op, p_table, op);
    elsif op = 'insert' then
      execute format(
        'create policy %I on public.%I for insert to authenticated with check (owner_id = (select auth.uid()))',
        'own_insert', p_table);
    elsif op = 'update' then
      execute format(
        'create policy %I on public.%I for update to authenticated
           using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()))',
        'own_update', p_table);
    end if;
  end loop;
end;
$$;

select public._apply_owner_policies('function_options',    array['select', 'insert', 'update']);
select public._apply_owner_policies('venues',              array['select', 'insert', 'update']);
select public._apply_owner_policies('sub_venues',          array['select', 'insert', 'update']);
select public._apply_owner_policies('sessions',            array['select', 'insert', 'update']);
select public._apply_owner_policies('tiers',               array['select', 'insert', 'update']);
select public._apply_owner_policies('elements',            array['select', 'insert', 'update']);
select public._apply_owner_policies('packages',            array['select', 'insert', 'update']);
select public._apply_owner_policies('package_elements',    array['select', 'insert', 'update', 'delete']);
select public._apply_owner_policies('vendors',             array['select', 'insert', 'update']);
select public._apply_owner_policies('vendor_rate_entries', array['select', 'insert']);
select public._apply_owner_policies('quotes',              array['select', 'insert', 'update']);
select public._apply_owner_policies('quote_items',         array['select', 'insert', 'update', 'delete']);
select public._apply_owner_policies('quote_charges',       array['select', 'insert', 'update', 'delete']);
select public._apply_owner_policies('rate_change_logs',    array['select', 'insert']);
select public._apply_owner_policies('audit_log',           array['select']);
select public._apply_owner_policies('quote_counters',      array[]::text[]);

drop function public._apply_owner_policies(text, text[]);

-- ---------- Profiles: own row only; only safe columns are editable ----------
