-- >>>>>>>>>> 0008_block_signups.sql
-- =============================================================================
-- 0008_block_signups.sql — database-level sign-up lock.
-- New rows in auth.users are only allowed when created through
-- public.create_app_user(), which sets a transaction-local flag. Any public
-- sign-up (or Dashboard "Add user") is rejected, even if the Dashboard toggle
-- "Allow new users to sign up" is left on.
-- Safe to re-run (idempotent).
-- =============================================================================

create or replace function public.block_public_signups()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(current_setting('app.allow_user_create', true), '') <> 'on' then
    raise exception 'Sign-ups are disabled. Accounts are created by the administrator.'
      using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function public.block_public_signups() from public, anon, authenticated;

drop trigger if exists block_public_signups on auth.users;
create trigger block_public_signups
  before insert on auth.users
  for each row execute function public.block_public_signups();

-- Re-define create_app_user so it opens the lock only for its own insert.
create or replace function public.create_app_user(
  p_phone     text,
  p_full_name text,
  p_password  text default 'ambria@123'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text := public.normalize_phone(p_phone);
  v_email text;
  v_id    uuid := gen_random_uuid();
begin
  if v_phone is null then
    raise exception 'Invalid phone number: %. Use a 10-digit Indian mobile number.', p_phone;
  end if;
  if length(coalesce(p_password, '')) < 6 then
    raise exception 'Password must be at least 6 characters (Supabase minimum).';
  end if;

  v_email := v_phone || '@phone.invalid';
  if exists (select 1 from auth.users where email = v_email) then
    raise exception 'A user with phone % already exists.', v_phone;
  end if;

  perform set_config('app.allow_user_create', 'on', true);

  -- Token columns must be '' (not NULL) or Supabase Auth fails to sign the user in.
  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change
  ) values (
    '00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email,
    extensions.crypt(p_password, extensions.gen_salt('bf')), now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('full_name', p_full_name, 'phone', v_phone),
    now(), now(), '', '', '', ''
  );

  perform set_config('app.allow_user_create', 'off', true);

  insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (
    gen_random_uuid(), v_id, v_id::text,
    jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true),
    'email', now(), now(), now()
  );

  return v_id;
end;
$$;
revoke all on function public.create_app_user(text, text, text) from public, anon, authenticated;

-- >>>>>>>>>> 0009_elements.sql
-- =============================================================================
-- 0009_elements.sql — element rate history, write rate limit, update RPC.
--
-- * Every element insert logs its initial rate; every default_rate change logs
--   old -> new (+ reason) to rate_change_logs as 'master_rate'. Done by trigger,
--   so no code path can change a rate without leaving history.
-- * rate_change_logs is now written ONLY by database code (triggers / RPCs);
--   users can read their history but not insert fake rows.
-- * Element writes are rate limited per user (60 / minute).
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- History is server-written only ---------------------------------
drop policy if exists own_insert on public.rate_change_logs;
revoke insert on public.rate_change_logs from authenticated;

-- ---------- Rate limit on element writes ------------------------------------
create or replace function public.elements_rate_limit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- auth.uid() is null for SQL Editor / server jobs — those aren't rate limited.
  if auth.uid() is not null then
    perform public.enforce_rate_limit('elements_write', 60, 60);
  end if;
  return new;
end;
$$;
drop trigger if exists elements_rate_limit on public.elements;
create trigger elements_rate_limit before insert or update on public.elements
  for each row execute function public.elements_rate_limit();

-- ---------- Master rate history ---------------------------------------------
create or replace function public.elements_log_rate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.rate_change_logs (owner_id, change_type, element_id, element_name, old_rate, new_rate, reason, changed_by)
    values (new.owner_id, 'master_rate', new.id, new.name, null, new.default_rate, 'Initial rate',
            coalesce(auth.uid(), new.owner_id));
  elsif new.default_rate is distinct from old.default_rate then
    insert into public.rate_change_logs (owner_id, change_type, element_id, element_name, old_rate, new_rate, reason, changed_by)
    values (new.owner_id, 'master_rate', new.id, new.name, old.default_rate, new.default_rate,
            nullif(btrim(coalesce(current_setting('app.rate_change_reason', true), '')), ''),
            coalesce(auth.uid(), new.owner_id));
  end if;
  return null;
end;
$$;
revoke all on function public.elements_log_rate() from public, anon, authenticated;

drop trigger if exists elements_log_rate on public.elements;
create trigger elements_log_rate after insert or update on public.elements
  for each row execute function public.elements_log_rate();

-- ---------- Update with an optional reason for the rate change ---------------
-- security invoker: RLS still decides which rows the caller can update.
create or replace function public.update_element(
  p_id           uuid,
  p_name         text,
  p_unit         text,
  p_default_rate numeric,
  p_default_qty  numeric,
  p_image_path   text,
  p_reason       text default null
)
returns public.elements
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v public.elements;
begin
  if p_reason is not null and length(p_reason) > 500 then
    raise exception 'Reason must be 500 characters or fewer.' using errcode = '23514';
  end if;

  perform set_config('app.rate_change_reason', coalesce(p_reason, ''), true);

  update public.elements
     set name         = btrim(p_name),
         unit         = nullif(btrim(coalesce(p_unit, '')), ''),
         default_rate = p_default_rate,
         default_qty  = p_default_qty,
         image_path   = p_image_path
   where id = p_id
  returning * into v;

  perform set_config('app.rate_change_reason', '', true);

  if v.id is null then
    raise exception 'Element not found.' using errcode = 'P0002';
  end if;
  return v;
end;
$$;
revoke all on function public.update_element(uuid, text, text, numeric, numeric, text, text) from public, anon;
grant execute on function public.update_element(uuid, text, text, numeric, numeric, text, text) to authenticated;

-- >>>>>>>>>> 0010_packages.sql
-- =============================================================================
-- 0010_packages.sql — package save RPC (package + element mapping in one
-- transaction), list view with element count/total, write rate limit.
-- Packages stay function-independent: nothing here references functions.
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Rate limit on package writes ------------------------------------
create or replace function public.packages_rate_limit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if auth.uid() is not null then
    perform public.enforce_rate_limit('packages_write', 60, 60);
  end if;
  return new;
end;
$$;
drop trigger if exists packages_rate_limit on public.packages;
create trigger packages_rate_limit before insert or update on public.packages
  for each row execute function public.packages_rate_limit();

-- ---------- List view --------------------------------------------------------
-- security_invoker: the caller's RLS applies to every table in the view.
create or replace view public.package_summaries
with (security_invoker = true) as
select
  p.id,
  p.owner_id,
  p.name,
  p.tier_id,
  t.name       as tier_name,
  t.sort_order as tier_sort,
  p.display_price,
  p.description,
  p.image_path,
  p.video_url,
  p.is_active,
  p.created_at,
  p.updated_at,
  count(pe.id)::integer as element_count,
  coalesce(sum(round(pe.default_qty * e.default_rate, 2)), 0)::numeric(14, 2) as elements_total
from public.packages p
join public.tiers t on t.id = p.tier_id
left join public.package_elements pe on pe.package_id = p.id
left join public.elements e on e.id = pe.element_id
group by p.id, t.id;

revoke all on public.package_summaries from anon, authenticated;
grant select on public.package_summaries to authenticated;

-- ---------- Save package + elements atomically --------------------------------
-- p_items: [{ "element_id": uuid, "default_qty": number, "sort_order": int? }, ...]
-- security invoker: RLS + composite FKs keep everything inside the caller's data.
create or replace function public.save_package(
  p_id            uuid,
  p_name          text,
  p_tier_id       uuid,
  p_display_price numeric,
  p_description   text,
  p_image_path    text,
  p_video_url     text,
  p_is_active     boolean,
  p_items         jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Add at least one element to the package.' using errcode = '23514';
  end if;

  if (select count(*) from jsonb_array_elements(p_items))
     <> (select count(distinct e ->> 'element_id') from jsonb_array_elements(p_items) e) then
    raise exception 'Each element can be added only once.' using errcode = '23514';
  end if;

  if p_id is null then
    insert into public.packages (name, tier_id, display_price, description, image_path, video_url, is_active)
    values (btrim(p_name), p_tier_id, p_display_price, nullif(btrim(coalesce(p_description, '')), ''),
            p_image_path, nullif(btrim(coalesce(p_video_url, '')), ''), coalesce(p_is_active, true))
    returning id into v_id;
  else
    update public.packages
       set name          = btrim(p_name),
           tier_id       = p_tier_id,
           display_price = p_display_price,
           description   = nullif(btrim(coalesce(p_description, '')), ''),
           image_path    = p_image_path,
           video_url     = nullif(btrim(coalesce(p_video_url, '')), ''),
           is_active     = coalesce(p_is_active, is_active)
     where id = p_id
    returning id into v_id;
    if v_id is null then
      raise exception 'Package not found.' using errcode = 'P0002';
    end if;
  end if;

  -- Archived elements may stay in a package they were already in, but can't be newly added.
  if exists (
    select 1
    from jsonb_array_elements(p_items) e
    join public.elements el on el.id = (e ->> 'element_id')::uuid
    where not el.is_active
      and not exists (
        select 1 from public.package_elements pe where pe.package_id = v_id and pe.element_id = el.id
      )
  ) then
    raise exception 'Archived elements can''t be added to a package.' using errcode = '23514';
  end if;

  delete from public.package_elements pe
   where pe.package_id = v_id
     and pe.element_id not in (select (e ->> 'element_id')::uuid from jsonb_array_elements(p_items) e);

  insert into public.package_elements (package_id, element_id, default_qty, sort_order)
  select v_id,
         (t.e ->> 'element_id')::uuid,
         (t.e ->> 'default_qty')::numeric,
         coalesce((t.e ->> 'sort_order')::integer, t.ord::integer)
  from jsonb_array_elements(p_items) with ordinality as t(e, ord)
  on conflict (package_id, element_id)
  do update set default_qty = excluded.default_qty, sort_order = excluded.sort_order;

  return v_id;
end;
$$;
revoke all on function public.save_package(uuid, text, uuid, numeric, text, text, text, boolean, jsonb) from public, anon;
grant execute on function public.save_package(uuid, text, uuid, numeric, text, text, text, boolean, jsonb) to authenticated;

-- >>>>>>>>>> 0011_save_quote.sql
-- =============================================================================
-- 0011_save_quote.sql — save a quotation in one transaction.
--
-- save_quote(p_payload jsonb) -> jsonb { id, quote_no }
-- * The SERVER builds the snapshot: function/venue/sub-venue/session names come from the
--   caller's own option tables, package name/tier and element name/unit/image/master rate
--   from the caller's catalogue. The client only sends ids, qty, rate, charges.
-- * The SERVER computes every amount: line = round(qty*rate,2), subtotal = Σ included,
--   final = subtotal + charges. Client totals are never trusted.
-- * Rates that differ from the element's master rate are logged as 'quote_override'
--   (only when new or changed since the last save of that quote — history is append-only).
-- * Re-saving a DRAFT quote updates it in place; sent/confirmed/cancelled quotes are frozen.
-- * security definer (needed to write rate history) — every reference is pinned to
--   auth.uid() through owner_id + composite foreign keys, so no other user's data can be used.
--
-- Payload:
-- { "quote_id": uuid|null,
--   "guest": { "source": "manual|lms_lead|lms_contract", "source_ref": text|null, "source_raw": json|null,
--              "guest_name": text, "guest_phone": text, "function_id": uuid, "venue_id": uuid,
--              "sub_venue_id": uuid|null, "event_date": "YYYY-MM-DD", "session_id": uuid },
--   "package_id": uuid,
--   "lines":   [ { "element_id": uuid, "qty": number, "rate": number, "included": bool } ],
--   "charges": [ { "description": text, "amount": number } ],
--   "notes": text|null }
-- Safe to re-run (idempotent).
-- =============================================================================

create or replace function public.save_quote(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := auth.uid();
  v_quote_id  uuid := nullif(p_payload ->> 'quote_id', '')::uuid;
  g           jsonb := p_payload -> 'guest';
  v_lines     jsonb := coalesce(p_payload -> 'lines', '[]'::jsonb);
  v_charges   jsonb := coalesce(p_payload -> 'charges', '[]'::jsonb);
  v_phone     text;
  v_function  text;
  v_venue     text;
  v_sub_venue text;
  v_session   text;
  v_pkg_name  text;
  v_pkg_tier  text;
  v_subtotal  numeric(14, 2);
  v_charges_t numeric(14, 2);
  v_status    public.quote_status;
  v_no        text;
  v_bad       integer;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform public.enforce_rate_limit('quote_save', 20, 60);

  if g is null or jsonb_typeof(g) <> 'object' then
    raise exception 'Guest details are missing.' using errcode = '23514';
  end if;
  if jsonb_typeof(v_lines) <> 'array' or jsonb_typeof(v_charges) <> 'array' then
    raise exception 'Invalid quote payload.' using errcode = '22023';
  end if;
  if jsonb_array_length(v_lines) > 300 or jsonb_array_length(v_charges) > 30 then
    raise exception 'Too many lines in this quote.' using errcode = '23514';
  end if;
  if not exists (select 1 from jsonb_array_elements(v_lines) l where coalesce((l ->> 'included')::boolean, true)) then
    raise exception 'Include at least one element.' using errcode = '23514';
  end if;
  if (select count(*) from jsonb_array_elements(v_lines))
     <> (select count(distinct l ->> 'element_id') from jsonb_array_elements(v_lines) l) then
    raise exception 'Each element can appear only once.' using errcode = '23514';
  end if;

  v_phone := public.normalize_phone(g ->> 'guest_phone');
  if v_phone is null then
    raise exception 'Enter a valid 10-digit mobile number.' using errcode = '23514';
  end if;
  if nullif(g ->> 'event_date', '') is null then
    raise exception 'Choose the event date.' using errcode = '23514';
  end if;

  -- Snapshot names, all from the caller's own rows (RLS is bypassed, so filter by owner explicitly).
  select name into v_function from public.function_options where id = (g ->> 'function_id')::uuid and owner_id = v_uid;
  select name into v_venue    from public.venues           where id = (g ->> 'venue_id')::uuid    and owner_id = v_uid;
  select name into v_session  from public.sessions         where id = (g ->> 'session_id')::uuid  and owner_id = v_uid;
  if v_function is null or v_venue is null or v_session is null then
    raise exception 'Choose the function, venue and session again.' using errcode = '23514';
  end if;
  if nullif(g ->> 'sub_venue_id', '') is not null then
    select name into v_sub_venue from public.sub_venues
     where id = (g ->> 'sub_venue_id')::uuid and owner_id = v_uid and venue_id = (g ->> 'venue_id')::uuid;
    if v_sub_venue is null then
      raise exception 'The sub-venue does not belong to this venue.' using errcode = '23514';
    end if;
  end if;

  select p.name, t.name into v_pkg_name, v_pkg_tier
    from public.packages p join public.tiers t on t.id = p.tier_id
   where p.id = (p_payload ->> 'package_id')::uuid and p.owner_id = v_uid;
  if v_pkg_name is null then
    raise exception 'Choose the package again.' using errcode = '23514';
  end if;

  -- Every element must be the caller's.
  select count(*) into v_bad
    from jsonb_array_elements(v_lines) l
    left join public.elements e on e.id = (l ->> 'element_id')::uuid and e.owner_id = v_uid
   where e.id is null;
  if v_bad > 0 then
    raise exception 'One of the elements is no longer available.' using errcode = '23503';
  end if;

  -- Server-side totals (qty/rate range checks are enforced by quote_items constraints).
  select coalesce(sum(round((l ->> 'qty')::numeric * (l ->> 'rate')::numeric, 2)), 0)
    into v_subtotal
    from jsonb_array_elements(v_lines) l
   where coalesce((l ->> 'included')::boolean, true);
  select coalesce(sum((c ->> 'amount')::numeric), 0) into v_charges_t from jsonb_array_elements(v_charges) c;

  if v_quote_id is null then
    insert into public.quotes (
      owner_id, source, source_ref, source_raw, guest_name, guest_phone, venue_name, sub_venue_name,
      event_date, session_name, function_name, package_id, package_name, package_tier,
      elements_subtotal, charges_total, final_total, notes
    ) values (
      v_uid, coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source, nullif(g ->> 'source_ref', ''),
      g -> 'source_raw', btrim(g ->> 'guest_name'), v_phone, v_venue, v_sub_venue,
      (g ->> 'event_date')::date, v_session, v_function, (p_payload ->> 'package_id')::uuid, v_pkg_name, v_pkg_tier,
      v_subtotal, v_charges_t, v_subtotal + v_charges_t, nullif(btrim(coalesce(p_payload ->> 'notes', '')), '')
    )
    returning id, quote_no into v_quote_id, v_no;
  else
    select status, quote_no into v_status, v_no from public.quotes where id = v_quote_id and owner_id = v_uid for update;
    if v_status is null then
      raise exception 'Quote not found.' using errcode = 'P0002';
    end if;
    if v_status <> 'draft' then
      raise exception 'Quote % is % and can no longer be edited.', v_no, v_status using errcode = '23514';
    end if;
    update public.quotes set
      source = coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source,
      source_ref = nullif(g ->> 'source_ref', ''), source_raw = g -> 'source_raw',
      guest_name = btrim(g ->> 'guest_name'), guest_phone = v_phone,
      venue_name = v_venue, sub_venue_name = v_sub_venue, event_date = (g ->> 'event_date')::date,
      session_name = v_session, function_name = v_function,
      package_id = (p_payload ->> 'package_id')::uuid, package_name = v_pkg_name, package_tier = v_pkg_tier,
      elements_subtotal = v_subtotal, charges_total = v_charges_t, final_total = v_subtotal + v_charges_t,
      notes = nullif(btrim(coalesce(p_payload ->> 'notes', '')), '')
    where id = v_quote_id;
    delete from public.quote_items where quote_id = v_quote_id;
    delete from public.quote_charges where quote_id = v_quote_id;
  end if;

  insert into public.quote_items (
    owner_id, quote_id, element_id, element_name, unit, image_path, master_rate_at_quote,
    qty, rate, amount, is_included, sort_order
  )
  select v_uid, v_quote_id, e.id, e.name, e.unit, e.image_path, e.default_rate,
         (t.l ->> 'qty')::numeric, (t.l ->> 'rate')::numeric,
         round((t.l ->> 'qty')::numeric * (t.l ->> 'rate')::numeric, 2),
         coalesce((t.l ->> 'included')::boolean, true), t.ord::integer
    from jsonb_array_elements(v_lines) with ordinality as t(l, ord)
    join public.elements e on e.id = (t.l ->> 'element_id')::uuid and e.owner_id = v_uid;

  insert into public.quote_charges (owner_id, quote_id, description, amount, sort_order)
  select v_uid, v_quote_id, btrim(t.c ->> 'description'), (t.c ->> 'amount')::numeric, t.ord::integer
    from jsonb_array_elements(v_charges) with ordinality as t(c, ord);

  -- Quote-specific rate overrides -> Rate History (new or changed since this quote's last log).
  insert into public.rate_change_logs (owner_id, change_type, element_id, element_name, quote_id, old_rate, new_rate, reason, changed_by)
  select v_uid, 'quote_override', qi.element_id, qi.element_name, v_quote_id, qi.master_rate_at_quote, qi.rate,
         'Rate changed for quote ' || v_no, v_uid
    from public.quote_items qi
   where qi.quote_id = v_quote_id
     and qi.is_included
     and qi.rate is distinct from qi.master_rate_at_quote
     and qi.rate is distinct from (
       select r.new_rate from public.rate_change_logs r
        where r.quote_id = v_quote_id and r.element_id = qi.element_id and r.change_type = 'quote_override'
        order by r.changed_at desc, r.id desc limit 1
     );

  return jsonb_build_object('id', v_quote_id, 'quote_no', v_no);
end;
$$;
revoke all on function public.save_quote(jsonb) from public, anon;
grant execute on function public.save_quote(jsonb) to authenticated;

-- >>>>>>>>>> 0012_ledger.sql
-- =============================================================================
-- 0012_ledger.sql — Rate History support.
-- * vendor_rate_history view: each vendor purchase entry with element/vendor names and
--   its trend vs the previous (non-voided) purchase of the same element, ordered by
--   purchase date: 'new' (first), 'up', 'down', 'same'. Voided entries are listed with
--   trend 'void' and are ignored when computing others' trends.
-- * Write rate limits on vendors and vendor purchase entries (60 / minute / user).
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Generic per-user write limit trigger ----------------------------
-- Usage: ... execute function public.rate_limit_writes('<action>', '<limit>', '<window seconds>')
create or replace function public.rate_limit_writes()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if auth.uid() is not null then
    perform public.enforce_rate_limit(tg_argv[0], tg_argv[1]::integer, tg_argv[2]::integer);
  end if;
  return new;
end;
$$;

drop trigger if exists vendors_rate_limit on public.vendors;
create trigger vendors_rate_limit before insert or update on public.vendors
  for each row execute function public.rate_limit_writes('vendors_write', '60', '60');

drop trigger if exists vendor_rates_rate_limit on public.vendor_rate_entries;
create trigger vendor_rates_rate_limit before insert or update on public.vendor_rate_entries
  for each row execute function public.rate_limit_writes('vendor_rates_write', '60', '60');

-- ---------- Vendor purchase history with trend -------------------------------
create or replace view public.vendor_rate_history
with (security_invoker = true) as
with ordered as (
  select
    r.*,
    lag(r.rate_per_unit) over (
      partition by r.owner_id, r.element_id
      order by r.purchase_date, r.logged_at, r.id
    ) as prev_rate
  from public.vendor_rate_entries r
  where r.voided_at is null
)
select
  r.id,
  r.owner_id,
  r.element_id,
  e.name  as element_name,
  e.unit  as element_unit,
  r.vendor_id,
  v.name  as vendor_name,
  r.purchase_date,
  r.qty,
  r.unit,
  r.rate_per_unit,
  r.remarks,
  r.logged_by,
  p.full_name as logged_by_name,
  r.logged_at,
  r.voided_at,
  r.void_reason,
  o.prev_rate,
  case
    when r.voided_at is not null then 'void'
    when o.prev_rate is null then 'new'
    when r.rate_per_unit > o.prev_rate then 'up'
    when r.rate_per_unit < o.prev_rate then 'down'
    else 'same'
  end as trend
from public.vendor_rate_entries r
join public.elements e on e.id = r.element_id
join public.vendors v on v.id = r.vendor_id
left join public.profiles p on p.id = r.logged_by
left join ordered o on o.id = r.id;

revoke all on public.vendor_rate_history from anon, authenticated;
grant select on public.vendor_rate_history to authenticated;

-- >>>>>>>>>> 0013_multi_package.sql
-- =============================================================================
-- 0013_multi_package.sql — a quote can include several packages.
--
-- * quote_packages: one row per package in a quote (snapshot name/tier + subtotal).
-- * quote_items.quote_package_id: which package section a line belongs to. The same
--   element may appear in two packages (separate lines); within one package only once.
-- * quotes.package_id/name/tier stay for compatibility: first package id, and all names /
--   tiers joined with " + " (used by the ledger column).
-- * save_quote accepts { packages: [ { package_id, lines: [...] } ] }. The old single
--   package payload ({ package_id, lines }) still works.
-- * Existing quotes are back-filled into quote_packages.
-- Safe to re-run (idempotent).
-- =============================================================================

create table if not exists public.quote_packages (
  id           uuid primary key default gen_random_uuid(),
  owner_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  quote_id     uuid not null,
  package_id   uuid,
  package_name text not null,
  package_tier text,
  subtotal     numeric(14, 2) not null default 0 check (subtotal >= 0),
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now(),
  unique (owner_id, id),
  foreign key (owner_id, quote_id) references public.quotes (owner_id, id),
  foreign key (owner_id, package_id) references public.packages (owner_id, id)
);
create index if not exists quote_packages_owner_quote_idx on public.quote_packages (owner_id, quote_id, sort_order);
create index if not exists quote_packages_owner_package_idx on public.quote_packages (owner_id, package_id);

alter table public.quote_items add column if not exists quote_package_id uuid references public.quote_packages (id) on delete cascade;
create index if not exists quote_items_package_idx on public.quote_items (quote_package_id);

-- RLS: same as other quote children (own rows; frozen once the quote leaves draft).
alter table public.quote_packages enable row level security;
revoke all on public.quote_packages from anon, authenticated;
grant select, insert, update, delete on public.quote_packages to authenticated;
drop policy if exists own_select on public.quote_packages;
drop policy if exists own_insert on public.quote_packages;
drop policy if exists own_update on public.quote_packages;
drop policy if exists own_delete on public.quote_packages;
create policy own_select on public.quote_packages for select to authenticated using (owner_id = (select auth.uid()));
create policy own_insert on public.quote_packages for insert to authenticated with check (owner_id = (select auth.uid()));
create policy own_update on public.quote_packages for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy own_delete on public.quote_packages for delete to authenticated using (owner_id = (select auth.uid()));

drop trigger if exists quote_packages_guard on public.quote_packages;
create trigger quote_packages_guard before insert or update or delete on public.quote_packages
  for each row execute function public.quote_children_guard();

-- ---------- Back-fill existing quotes (one section = the quote's package) -----------
-- Guards are paused so frozen (sent/confirmed) quotes can be back-filled; nothing else changes.
alter table public.quote_packages disable trigger quote_packages_guard;
alter table public.quote_items disable trigger quote_items_guard;

insert into public.quote_packages (owner_id, quote_id, package_id, package_name, package_tier, subtotal, sort_order)
select q.owner_id, q.id, q.package_id, coalesce(q.package_name, 'Package'), q.package_tier, q.elements_subtotal, 1
  from public.quotes q
 where not exists (select 1 from public.quote_packages qp where qp.quote_id = q.id);

update public.quote_items qi
   set quote_package_id = qp.id
  from public.quote_packages qp
 where qp.quote_id = qi.quote_id and qi.quote_package_id is null;

alter table public.quote_packages enable trigger quote_packages_guard;
alter table public.quote_items enable trigger quote_items_guard;

-- ---------- save_quote with several packages ----------------------------------------
create or replace function public.save_quote(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := auth.uid();
  v_quote_id  uuid := nullif(p_payload ->> 'quote_id', '')::uuid;
  g           jsonb := p_payload -> 'guest';
  v_packages  jsonb;
  v_charges   jsonb := coalesce(p_payload -> 'charges', '[]'::jsonb);
  v_all_lines jsonb;
  v_phone     text;
  v_function  text;
  v_venue     text;
  v_sub_venue text;
  v_session   text;
  v_names     text;
  v_tiers     text;
  v_first_pkg uuid;
  v_subtotal  numeric(14, 2);
  v_charges_t numeric(14, 2);
  v_status    public.quote_status;
  v_no        text;
  v_bad       integer;
  v_block     record;
  v_qp_id     uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform public.enforce_rate_limit('quote_save', 20, 60);

  -- Old single-package payload -> one block.
  v_packages := coalesce(
    p_payload -> 'packages',
    case when p_payload ? 'package_id'
         then jsonb_build_array(jsonb_build_object('package_id', p_payload -> 'package_id', 'lines', coalesce(p_payload -> 'lines', '[]'::jsonb)))
    end,
    '[]'::jsonb
  );

  if g is null or jsonb_typeof(g) <> 'object' then
    raise exception 'Guest details are missing.' using errcode = '23514';
  end if;
  if jsonb_typeof(v_packages) <> 'array' or jsonb_typeof(v_charges) <> 'array' then
    raise exception 'Invalid quote payload.' using errcode = '22023';
  end if;
  if jsonb_array_length(v_packages) = 0 then
    raise exception 'Choose the package again.' using errcode = '23514';
  end if;
  if jsonb_array_length(v_packages) > 20 or jsonb_array_length(v_charges) > 30 then
    raise exception 'Too many lines in this quote.' using errcode = '23514';
  end if;
  if (select count(*) from jsonb_array_elements(v_packages))
     <> (select count(distinct b ->> 'package_id') from jsonb_array_elements(v_packages) b) then
    raise exception 'Each package can be added only once.' using errcode = '23514';
  end if;

  -- All lines with their package, for checks.
  select coalesce(jsonb_agg(l || jsonb_build_object('_pkg', b ->> 'package_id')), '[]'::jsonb)
    into v_all_lines
    from jsonb_array_elements(v_packages) b, jsonb_array_elements(coalesce(b -> 'lines', '[]'::jsonb)) l;

  if jsonb_array_length(v_all_lines) > 300 then
    raise exception 'Too many lines in this quote.' using errcode = '23514';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_packages) b
     where not exists (
       select 1 from jsonb_array_elements(coalesce(b -> 'lines', '[]'::jsonb)) l where coalesce((l ->> 'included')::boolean, true)
     )
  ) then
    raise exception 'Include at least one element.' using errcode = '23514';
  end if;
  if (select count(*) from jsonb_array_elements(v_all_lines))
     <> (select count(distinct (l ->> '_pkg') || ':' || (l ->> 'element_id')) from jsonb_array_elements(v_all_lines) l) then
    raise exception 'Each element can appear only once.' using errcode = '23514';
  end if;

  v_phone := public.normalize_phone(g ->> 'guest_phone');
  if v_phone is null then
    raise exception 'Enter a valid 10-digit mobile number.' using errcode = '23514';
  end if;
  if nullif(g ->> 'event_date', '') is null then
    raise exception 'Choose the event date.' using errcode = '23514';
  end if;

  select name into v_function from public.function_options where id = (g ->> 'function_id')::uuid and owner_id = v_uid;
  select name into v_venue    from public.venues           where id = (g ->> 'venue_id')::uuid    and owner_id = v_uid;
  select name into v_session  from public.sessions         where id = (g ->> 'session_id')::uuid  and owner_id = v_uid;
  if v_function is null or v_venue is null or v_session is null then
    raise exception 'Choose the function, venue and session again.' using errcode = '23514';
  end if;
  if nullif(g ->> 'sub_venue_id', '') is not null then
    select name into v_sub_venue from public.sub_venues
     where id = (g ->> 'sub_venue_id')::uuid and owner_id = v_uid and venue_id = (g ->> 'venue_id')::uuid;
    if v_sub_venue is null then
      raise exception 'The sub-venue does not belong to this venue.' using errcode = '23514';
    end if;
  end if;

  -- Packages must be the caller's.
  select count(*) into v_bad
    from jsonb_array_elements(v_packages) b
    left join public.packages p on p.id = (b ->> 'package_id')::uuid and p.owner_id = v_uid
   where p.id is null;
  if v_bad > 0 then
    raise exception 'Choose the package again.' using errcode = '23514';
  end if;

  select string_agg(p.name, ' + ' order by t.ord), string_agg(tr.name, ' + ' order by t.ord),
         (array_agg(p.id order by t.ord))[1]
    into v_names, v_tiers, v_first_pkg
    from jsonb_array_elements(v_packages) with ordinality as t(b, ord)
    join public.packages p on p.id = (t.b ->> 'package_id')::uuid
    join public.tiers tr on tr.id = p.tier_id;

  -- Elements must be the caller's.
  select count(*) into v_bad
    from jsonb_array_elements(v_all_lines) l
    left join public.elements e on e.id = (l ->> 'element_id')::uuid and e.owner_id = v_uid
   where e.id is null;
  if v_bad > 0 then
    raise exception 'One of the elements is no longer available.' using errcode = '23503';
  end if;

  select coalesce(sum(round((l ->> 'qty')::numeric * (l ->> 'rate')::numeric, 2)), 0)
    into v_subtotal
    from jsonb_array_elements(v_all_lines) l
   where coalesce((l ->> 'included')::boolean, true);
  select coalesce(sum((c ->> 'amount')::numeric), 0) into v_charges_t from jsonb_array_elements(v_charges) c;

  if v_quote_id is null then
    insert into public.quotes (
      owner_id, source, source_ref, source_raw, guest_name, guest_phone, venue_name, sub_venue_name,
      event_date, session_name, function_name, package_id, package_name, package_tier,
      elements_subtotal, charges_total, final_total, notes
    ) values (
      v_uid, coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source, nullif(g ->> 'source_ref', ''),
      g -> 'source_raw', btrim(g ->> 'guest_name'), v_phone, v_venue, v_sub_venue,
      (g ->> 'event_date')::date, v_session, v_function, v_first_pkg, v_names, v_tiers,
      v_subtotal, v_charges_t, v_subtotal + v_charges_t, nullif(btrim(coalesce(p_payload ->> 'notes', '')), '')
    )
    returning id, quote_no into v_quote_id, v_no;
  else
    select status, quote_no into v_status, v_no from public.quotes where id = v_quote_id and owner_id = v_uid for update;
    if v_status is null then
      raise exception 'Quote not found.' using errcode = 'P0002';
    end if;
    if v_status <> 'draft' then
      raise exception 'Quote % is % and can no longer be edited.', v_no, v_status using errcode = '23514';
    end if;
    update public.quotes set
      source = coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source,
      source_ref = nullif(g ->> 'source_ref', ''), source_raw = g -> 'source_raw',
      guest_name = btrim(g ->> 'guest_name'), guest_phone = v_phone,
      venue_name = v_venue, sub_venue_name = v_sub_venue, event_date = (g ->> 'event_date')::date,
      session_name = v_session, function_name = v_function,
      package_id = v_first_pkg, package_name = v_names, package_tier = v_tiers,
      elements_subtotal = v_subtotal, charges_total = v_charges_t, final_total = v_subtotal + v_charges_t,
      notes = nullif(btrim(coalesce(p_payload ->> 'notes', '')), '')
    where id = v_quote_id;
    delete from public.quote_items where quote_id = v_quote_id;
    delete from public.quote_packages where quote_id = v_quote_id;
    delete from public.quote_charges where quote_id = v_quote_id;
  end if;

  -- One section per package, then its lines.
  for v_block in
    select t.b, t.ord, p.id as pid, p.name as pname, tr.name as ptier
      from jsonb_array_elements(v_packages) with ordinality as t(b, ord)
      join public.packages p on p.id = (t.b ->> 'package_id')::uuid
      join public.tiers tr on tr.id = p.tier_id
     order by t.ord
  loop
    insert into public.quote_packages (owner_id, quote_id, package_id, package_name, package_tier, subtotal, sort_order)
    values (
      v_uid, v_quote_id, v_block.pid, v_block.pname, v_block.ptier,
      (select coalesce(sum(round((l ->> 'qty')::numeric * (l ->> 'rate')::numeric, 2)), 0)
         from jsonb_array_elements(coalesce(v_block.b -> 'lines', '[]'::jsonb)) l
        where coalesce((l ->> 'included')::boolean, true)),
      v_block.ord::integer
    )
    returning id into v_qp_id;

    insert into public.quote_items (
      owner_id, quote_id, quote_package_id, element_id, element_name, unit, image_path, master_rate_at_quote,
      qty, rate, amount, is_included, sort_order
    )
    select v_uid, v_quote_id, v_qp_id, e.id, e.name, e.unit, e.image_path, e.default_rate,
           (t.l ->> 'qty')::numeric, (t.l ->> 'rate')::numeric,
           round((t.l ->> 'qty')::numeric * (t.l ->> 'rate')::numeric, 2),
           coalesce((t.l ->> 'included')::boolean, true), (v_block.ord * 1000 + t.ord)::integer
      from jsonb_array_elements(coalesce(v_block.b -> 'lines', '[]'::jsonb)) with ordinality as t(l, ord)
      join public.elements e on e.id = (t.l ->> 'element_id')::uuid and e.owner_id = v_uid;
  end loop;

  insert into public.quote_charges (owner_id, quote_id, description, amount, sort_order)
  select v_uid, v_quote_id, btrim(t.c ->> 'description'), (t.c ->> 'amount')::numeric, t.ord::integer
    from jsonb_array_elements(v_charges) with ordinality as t(c, ord);

  -- Quote-specific rate overrides -> Rate History (each element+rate logged once per quote).
  insert into public.rate_change_logs (owner_id, change_type, element_id, element_name, quote_id, old_rate, new_rate, reason, changed_by)
  select distinct on (qi.element_id, qi.rate)
         v_uid, 'quote_override', qi.element_id, qi.element_name, v_quote_id, qi.master_rate_at_quote, qi.rate,
         'Rate changed for quote ' || v_no, v_uid
    from public.quote_items qi
   where qi.quote_id = v_quote_id
     and qi.is_included
     and qi.rate is distinct from qi.master_rate_at_quote
     and not exists (
       select 1 from public.rate_change_logs r
        where r.quote_id = v_quote_id and r.element_id = qi.element_id
          and r.change_type = 'quote_override' and r.new_rate = qi.rate
     );

  return jsonb_build_object('id', v_quote_id, 'quote_no', v_no);
end;
$$;
revoke all on function public.save_quote(jsonb) from public, anon;
grant execute on function public.save_quote(jsonb) to authenticated;

-- >>>>>>>>>> 0014_pnl.sql
-- =============================================================================
-- 0014_pnl.sql — cost tracking and Profit & Loss.
--
-- Cost rules (agreed with the owner, 26 Oct 2026):
-- * Unit cost of an element = its fixed `unit_cost` if set, otherwise the latest
--   non-voided vendor purchase rate on or before the date (by purchase date).
--   Neither -> unknown. Unknown cost is NEVER treated as zero.
-- * Cost is locked when the quote is saved (quote_items.unit_cost_at_quote + cost_source).
-- * Additional charges are pass-through: cost = amount, profit 0.
-- * Margin % = profit / elements selling × 100 (null when selling is 0 or cost unknown).
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.elements add column if not exists unit_cost numeric(12, 2)
  check (unit_cost is null or unit_cost >= 0);

alter table public.quote_items add column if not exists cost_source text
  check (cost_source is null or cost_source in ('fixed', 'vendor'));

-- ---------- Cost resolution ----------------------------------------------------
create or replace function public.element_cost(p_element_id uuid, p_on date)
returns table (unit_cost numeric, source text)
language sql
stable
set search_path = ''
as $$
  select coalesce(e.unit_cost, v.rate_per_unit),
         case when e.unit_cost is not null then 'fixed' when v.rate_per_unit is not null then 'vendor' end
    from public.elements e
    left join lateral (
      select r.rate_per_unit
        from public.vendor_rate_entries r
       where r.owner_id = e.owner_id and r.element_id = e.id and r.voided_at is null
         and r.purchase_date <= p_on
       order by r.purchase_date desc, r.logged_at desc, r.id desc
       limit 1
    ) v on true
   where e.id = p_element_id;
$$;
grant execute on function public.element_cost(uuid, date) to authenticated;

-- ---------- Lock cost when a quote line is written ------------------------------
create or replace function public.quote_items_lock_cost()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  c      record;
  v_on   date := (now() at time zone 'Asia/Kolkata')::date;
  v_evt  date;
begin
  if new.element_id is not null and new.unit_cost_at_quote is null then
    -- Rates known at save time, and not later than the event itself.
    select event_date into v_evt from public.quotes where id = new.quote_id;
    if v_evt is not null and v_evt < v_on then
      v_on := v_evt;
    end if;
    select * into c from public.element_cost(new.element_id, v_on);
    new.unit_cost_at_quote := c.unit_cost;
    new.cost_source := c.source;
  end if;
  return new;
end;
$$;
drop trigger if exists quote_items_lock_cost on public.quote_items;
create trigger quote_items_lock_cost before insert on public.quote_items
  for each row execute function public.quote_items_lock_cost();

-- Back-fill quotes saved before cost tracking, using the cost as of the quote's creation day.
alter table public.quote_items disable trigger quote_items_guard;
update public.quote_items qi
   set unit_cost_at_quote = c.unit_cost, cost_source = c.source
  from (
    select x.id, ec.unit_cost, ec.source
      from public.quote_items x
      join public.quotes q on q.id = x.quote_id
      cross join lateral public.element_cost(
        x.element_id, least((q.created_at at time zone 'Asia/Kolkata')::date, coalesce(q.event_date, 'infinity'::date))
      ) ec
     where x.unit_cost_at_quote is null and x.cost_source is null and x.element_id is not null
  ) c
 where c.id = qi.id;
alter table public.quote_items enable trigger quote_items_guard;

-- ---------- update_element now also takes the unit cost ------------------------
drop function if exists public.update_element(uuid, text, text, numeric, numeric, text, text);
create or replace function public.update_element(
  p_id           uuid,
  p_name         text,
  p_unit         text,
  p_default_rate numeric,
  p_default_qty  numeric,
  p_image_path   text,
  p_unit_cost    numeric,
  p_reason       text default null
)
returns public.elements
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v public.elements;
begin
  if p_reason is not null and length(p_reason) > 500 then
    raise exception 'Reason must be 500 characters or fewer.' using errcode = '23514';
  end if;
  perform set_config('app.rate_change_reason', coalesce(p_reason, ''), true);
  update public.elements
     set name         = btrim(p_name),
         unit         = nullif(btrim(coalesce(p_unit, '')), ''),
         default_rate = p_default_rate,
         default_qty  = p_default_qty,
         image_path   = p_image_path,
         unit_cost    = p_unit_cost
   where id = p_id
  returning * into v;
  perform set_config('app.rate_change_reason', '', true);
  if v.id is null then
    raise exception 'Element not found.' using errcode = 'P0002';
  end if;
  return v;
end;
$$;
revoke all on function public.update_element(uuid, text, text, numeric, numeric, text, numeric, text) from public, anon;
grant execute on function public.update_element(uuid, text, text, numeric, numeric, text, numeric, text) to authenticated;

-- ---------- P&L views ------------------------------------------------------------
-- One row per included quote line.
create or replace view public.quote_item_pnl
with (security_invoker = true) as
select
  qi.id,
  qi.owner_id,
  qi.quote_id,
  qi.quote_package_id,
  qi.element_name,
  qi.unit,
  qi.qty,
  qi.rate,
  qi.amount                                   as selling,
  qi.unit_cost_at_quote                       as unit_cost,
  qi.cost_source,
  round(qi.qty * qi.unit_cost_at_quote, 2)    as cost,
  qi.amount - round(qi.qty * qi.unit_cost_at_quote, 2) as profit,
  case when qi.amount > 0 and qi.unit_cost_at_quote is not null
       then round((qi.amount - round(qi.qty * qi.unit_cost_at_quote, 2)) / qi.amount * 100, 2) end as margin_pct,
  qi.sort_order
from public.quote_items qi
where qi.is_included;

-- One row per quote. Costs/profit are null while any included line has no cost.
create or replace view public.quote_pnl
with (security_invoker = true) as
select
  q.id,
  q.owner_id,
  q.quote_no,
  q.status,
  q.created_at,
  q.event_date,
  q.guest_name,
  q.function_name,
  q.package_name,
  q.elements_subtotal                                   as elements_selling,
  q.charges_total,
  q.final_total,
  coalesce(l.known_cost, 0)                             as known_cost,
  coalesce(l.missing, 0)::integer                       as missing_cost_lines,
  case when coalesce(l.missing, 0) = 0 then coalesce(l.known_cost, 0) end as elements_cost,
  case when coalesce(l.missing, 0) = 0 then q.elements_subtotal - coalesce(l.known_cost, 0) end as profit,
  case when coalesce(l.missing, 0) = 0 and q.elements_subtotal > 0
       then round((q.elements_subtotal - coalesce(l.known_cost, 0)) / q.elements_subtotal * 100, 2) end as margin_pct
from public.quotes q
left join lateral (
  select sum(round(qi.qty * qi.unit_cost_at_quote, 2)) filter (where qi.unit_cost_at_quote is not null) as known_cost,
         count(*) filter (where qi.unit_cost_at_quote is null) as missing
    from public.quote_items qi
   where qi.quote_id = q.id and qi.is_included
) l on true;

revoke all on public.quote_item_pnl, public.quote_pnl from anon, authenticated;
grant select on public.quote_item_pnl, public.quote_pnl to authenticated;

-- ---------- Totals for the report header (respects RLS: security invoker) --------
create or replace function public.pnl_totals(
  p_statuses   public.quote_status[] default array['confirmed']::public.quote_status[],
  p_from       date default null,
  p_to         date default null,
  p_function   text default null,
  p_package_id uuid default null
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  with f as (
    select p.*
      from public.quote_pnl p
     where p.status = any (p_statuses)
       and (p_from is null or p.event_date >= p_from)
       and (p_to is null or p.event_date <= p_to)
       and (p_function is null or p.function_name = p_function)
       and (p_package_id is null or exists (
             select 1 from public.quote_packages qp where qp.quote_id = p.id and qp.package_id = p_package_id))
  )
  select jsonb_build_object(
    'quotes',            count(*),
    'complete_quotes',   count(*) filter (where missing_cost_lines = 0),
    'incomplete_quotes', count(*) filter (where missing_cost_lines > 0),
    'elements_selling',  coalesce(sum(elements_selling) filter (where missing_cost_lines = 0), 0),
    'elements_cost',     coalesce(sum(elements_cost) filter (where missing_cost_lines = 0), 0),
    'profit',            coalesce(sum(profit) filter (where missing_cost_lines = 0), 0),
    'margin_pct',        case when coalesce(sum(elements_selling) filter (where missing_cost_lines = 0), 0) > 0
                              then round(sum(profit) filter (where missing_cost_lines = 0)
                                         / sum(elements_selling) filter (where missing_cost_lines = 0) * 100, 2) end,
    'charges_total',     coalesce(sum(charges_total), 0),
    'all_selling',       coalesce(sum(elements_selling), 0)
  )
  from f;
$$;
revoke all on function public.pnl_totals(public.quote_status[], date, date, text, uuid) from public, anon;
grant execute on function public.pnl_totals(public.quote_status[], date, date, text, uuid) to authenticated;

-- >>>>>>>>>> 0015_delete_catalogue.sql
-- =============================================================================
-- 0015_delete_catalogue.sql — permanently delete elements and packages.
--
-- Saved quotes and history keep their snapshots (names, rates, amounts); only their
-- links back to the deleted row are cleared (ON DELETE SET NULL on the id column).
-- * Package: always deletable. Its element mapping goes with it.
-- * Element: blocked while it is in any package (remove it there first) or has vendor
--   purchase history (cost records — archive instead). Quotes/rate logs keep their copy.
-- Use delete_element() / delete_package() for clear messages.
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Keep history rows when the element/package is deleted -------------
-- Composite FKs: null only the id column (owner_id stays) — needs PostgreSQL 15+.
alter table public.quote_items drop constraint if exists quote_items_owner_id_element_id_fkey;
alter table public.quote_items add constraint quote_items_owner_id_element_id_fkey
  foreign key (owner_id, element_id) references public.elements (owner_id, id) on delete set null (element_id);

alter table public.rate_change_logs drop constraint if exists rate_change_logs_owner_id_element_id_fkey;
alter table public.rate_change_logs add constraint rate_change_logs_owner_id_element_id_fkey
  foreign key (owner_id, element_id) references public.elements (owner_id, id) on delete set null (element_id);

alter table public.rate_change_logs drop constraint if exists rate_change_logs_owner_id_package_id_fkey;
alter table public.rate_change_logs add constraint rate_change_logs_owner_id_package_id_fkey
  foreign key (owner_id, package_id) references public.packages (owner_id, id) on delete set null (package_id);

alter table public.quotes drop constraint if exists quotes_owner_id_package_id_fkey;
alter table public.quotes add constraint quotes_owner_id_package_id_fkey
  foreign key (owner_id, package_id) references public.packages (owner_id, id) on delete set null (package_id);

alter table public.quote_packages drop constraint if exists quote_packages_owner_id_package_id_fkey;
alter table public.quote_packages add constraint quote_packages_owner_id_package_id_fkey
  foreign key (owner_id, package_id) references public.packages (owner_id, id) on delete set null (package_id);

-- package_elements → elements and vendor_rate_entries → elements stay RESTRICT (they block).

-- Frozen (sent/confirmed) quotes must still accept the link being cleared.
create or replace function public.quote_children_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_status public.quote_status;
  v_quote  uuid := coalesce(new.quote_id, old.quote_id);
begin
  -- Allow ON DELETE SET NULL on element/package links; snapshots are untouched.
  if tg_op = 'UPDATE'
     and (to_jsonb(new) - array['element_id', 'package_id']) = (to_jsonb(old) - array['element_id', 'package_id']) then
    return new;
  end if;
  select status into v_status from public.quotes where id = v_quote;
  if v_status is not null and v_status <> 'draft' then
    raise exception 'Quote is % — its lines are frozen.', v_status;
  end if;
  return coalesce(new, old);
end;
$$;

create or replace function public.quotes_before_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id <> old.owner_id or new.quote_no <> old.quote_no then
    raise exception 'owner and quote number cannot change';
  end if;

  if old.status <> 'draft' then
    -- package_id may be cleared when the package is deleted; the snapshot stays.
    if (to_jsonb(new) - array['status', 'notes', 'updated_at', 'package_id'])
       <> (to_jsonb(old) - array['status', 'notes', 'updated_at', 'package_id'])
       or (new.package_id is not null and new.package_id is distinct from old.package_id) then
      raise exception 'Quote % is % and can no longer be edited.', old.quote_no, old.status;
    end if;
  end if;

  if new.status <> old.status and not (
       (old.status = 'draft' and new.status in ('sent', 'confirmed', 'cancelled'))
    or (old.status = 'sent' and new.status in ('confirmed', 'cancelled'))
    or (old.status = 'confirmed' and new.status = 'cancelled')
  ) then
    raise exception 'Invalid status change: % -> %', old.status, new.status;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

-- ---------- Owners may delete their own elements/packages ----------------------
grant delete on public.elements, public.packages to authenticated;
drop policy if exists own_delete on public.elements;
drop policy if exists own_delete on public.packages;
create policy own_delete on public.elements for delete to authenticated using (owner_id = (select auth.uid()));
create policy own_delete on public.packages for delete to authenticated using (owner_id = (select auth.uid()));

-- ---------- RPCs with clear messages ----------------------------------------------
create or replace function public.delete_element(p_id uuid)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_image text;
  v_pkgs  integer;
  v_rates integer;
begin
  select image_path into v_image from public.elements where id = p_id;
  if not found then
    raise exception 'Element not found.' using errcode = 'P0002';
  end if;
  select count(*) into v_pkgs from public.package_elements where element_id = p_id;
  if v_pkgs > 0 then
    raise exception 'This element is in % package(s). Remove it from those packages first, or archive it.', v_pkgs
      using errcode = '23503', hint = 'in_packages';
  end if;
  select count(*) into v_rates from public.vendor_rate_entries where element_id = p_id;
  if v_rates > 0 then
    raise exception 'This element has vendor purchase history, which is kept for cost records. Archive it instead.'
      using errcode = '23503', hint = 'has_vendor_rates';
  end if;
  delete from public.elements where id = p_id;
  return jsonb_build_object('image_path', v_image);
end;
$$;

create or replace function public.delete_package(p_id uuid)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_image text;
begin
  select image_path into v_image from public.packages where id = p_id;
  if not found then
    raise exception 'Package not found.' using errcode = 'P0002';
  end if;
  delete from public.packages where id = p_id; -- package_elements cascade
  return jsonb_build_object('image_path', v_image);
end;
$$;

revoke all on function public.delete_element(uuid) from public, anon;
revoke all on function public.delete_package(uuid) from public, anon;
grant execute on function public.delete_element(uuid) to authenticated;
grant execute on function public.delete_package(uuid) to authenticated;

-- >>>>>>>>>> 0016_editable_quotes.sql
-- =============================================================================
-- 0016_editable_quotes.sql — quotes stay editable after being sent; re-sending is tracked.
--
-- * Draft and Sent quotes can be edited (re-saved). Confirmed and Cancelled are locked.
--   Editing a Sent quote keeps it Sent and logs an 'edited' entry in the audit log.
-- * mark_quote_sent(id): can be used again and again — bumps sent_count / last_sent_at,
--   sets status to sent (from draft or sent) and logs each repeat send.
-- * quotes now also store the option ids (function/venue/sub-venue/session) so a saved
--   quote can be reopened in the Studio with its form filled in.
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.quotes add column if not exists function_id  uuid;
alter table public.quotes add column if not exists venue_id     uuid;
alter table public.quotes add column if not exists sub_venue_id uuid;
alter table public.quotes add column if not exists session_id   uuid;
alter table public.quotes add column if not exists sent_count   integer not null default 0 check (sent_count >= 0);
alter table public.quotes add column if not exists last_sent_at timestamptz;

-- ---------- Lock only confirmed / cancelled quotes ---------------------------------
create or replace function public.quotes_before_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id <> old.owner_id or new.quote_no <> old.quote_no then
    raise exception 'owner and quote number cannot change';
  end if;

  if old.status in ('confirmed', 'cancelled') then
    -- package_id may be cleared when the package is deleted; the snapshot stays.
    if (to_jsonb(new) - array['status', 'notes', 'updated_at', 'package_id'])
       <> (to_jsonb(old) - array['status', 'notes', 'updated_at', 'package_id'])
       or (new.package_id is not null and new.package_id is distinct from old.package_id) then
      raise exception 'Quote % is % and can no longer be edited.', old.quote_no, old.status;
    end if;
  end if;

  if new.status <> old.status and not (
       (old.status = 'draft' and new.status in ('sent', 'confirmed', 'cancelled'))
    or (old.status = 'sent' and new.status in ('confirmed', 'cancelled'))
    or (old.status = 'confirmed' and new.status = 'cancelled')
  ) then
    raise exception 'Invalid status change: % -> %', old.status, new.status;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

create or replace function public.quote_children_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_status public.quote_status;
  v_quote  uuid := coalesce(new.quote_id, old.quote_id);
begin
  -- Allow ON DELETE SET NULL on element/package links; snapshots are untouched.
  if tg_op = 'UPDATE'
     and (to_jsonb(new) - array['element_id', 'package_id']) = (to_jsonb(old) - array['element_id', 'package_id']) then
    return new;
  end if;
  select status into v_status from public.quotes where id = v_quote;
  if v_status in ('confirmed', 'cancelled') then
    raise exception 'Quote is % — its lines are frozen.', v_status;
  end if;
  return coalesce(new, old);
end;
$$;

-- ---------- Back-fill (runs after the trigger change so sent quotes can be updated) ----
-- Option ids for older quotes, matched by the saved names (frozen columns: guard paused).
alter table public.quotes disable trigger quotes_before_update;
update public.quotes q set function_id = f.id
  from public.function_options f where q.function_id is null and f.owner_id = q.owner_id and f.name = q.function_name;
update public.quotes q set venue_id = v.id
  from public.venues v where q.venue_id is null and v.owner_id = q.owner_id and v.name = q.venue_name;
update public.quotes q set sub_venue_id = s.id
  from public.sub_venues s where q.sub_venue_id is null and q.sub_venue_name is not null
   and s.owner_id = q.owner_id and s.venue_id = q.venue_id and s.name = q.sub_venue_name;
update public.quotes q set session_id = s.id
  from public.sessions s where q.session_id is null and s.owner_id = q.owner_id and s.name = q.session_name;
-- Quotes already sent count as sent once.
update public.quotes set sent_count = 1, last_sent_at = coalesce(last_sent_at, updated_at)
 where status in ('sent', 'confirmed') and sent_count = 0;
alter table public.quotes enable trigger quotes_before_update;

-- ---------- Mark as sent (repeatable) ----------------------------------------------
create or replace function public.mark_quote_sent(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := auth.uid();
  v_status public.quote_status;
  v_count  integer;
  v_at     timestamptz := now();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform public.enforce_rate_limit('quote_status', 30, 60);
  select status into v_status from public.quotes where id = p_id and owner_id = v_uid for update;
  if v_status is null then
    raise exception 'Quote not found.' using errcode = 'P0002';
  end if;
  if v_status not in ('draft', 'sent') then
    raise exception 'A % quote can''t be sent again.', v_status using errcode = '23514';
  end if;
  update public.quotes
     set status = 'sent', sent_count = sent_count + 1, last_sent_at = v_at
   where id = p_id
  returning sent_count into v_count;
  -- The first send is logged as a status change by the audit trigger; repeats get their own entry.
  if v_status = 'sent' then
    insert into public.audit_log (owner_id, table_name, row_id, action, old_data, new_data)
    values (v_uid, 'quotes', p_id, 'sent', jsonb_build_object('status', 'sent'),
            jsonb_build_object('status', 'sent', 'sent_count', v_count));
  end if;
  return jsonb_build_object('sent_count', v_count, 'last_sent_at', v_at);
end;
$$;
revoke all on function public.mark_quote_sent(uuid) from public, anon;
grant execute on function public.mark_quote_sent(uuid) to authenticated;

-- ---------- save_quote: editable while draft or sent; stores option ids -------------
create or replace function public.save_quote(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := auth.uid();
  v_quote_id  uuid := nullif(p_payload ->> 'quote_id', '')::uuid;
  g           jsonb := p_payload -> 'guest';
  v_packages  jsonb;
  v_charges   jsonb := coalesce(p_payload -> 'charges', '[]'::jsonb);
  v_all_lines jsonb;
  v_phone     text;
  v_function  text;
  v_venue     text;
  v_sub_venue text;
  v_session   text;
  v_names     text;
  v_tiers     text;
  v_first_pkg uuid;
  v_subtotal  numeric(14, 2);
  v_charges_t numeric(14, 2);
  v_status    public.quote_status;
  v_no        text;
  v_bad       integer;
  v_block     record;
  v_qp_id     uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform public.enforce_rate_limit('quote_save', 20, 60);

  -- Old single-package payload -> one block.
  v_packages := coalesce(
    p_payload -> 'packages',
    case when p_payload ? 'package_id'
         then jsonb_build_array(jsonb_build_object('package_id', p_payload -> 'package_id', 'lines', coalesce(p_payload -> 'lines', '[]'::jsonb)))
    end,
    '[]'::jsonb
  );

  if g is null or jsonb_typeof(g) <> 'object' then
    raise exception 'Guest details are missing.' using errcode = '23514';
  end if;
  if jsonb_typeof(v_packages) <> 'array' or jsonb_typeof(v_charges) <> 'array' then
    raise exception 'Invalid quote payload.' using errcode = '22023';
  end if;
  if jsonb_array_length(v_packages) = 0 then
    raise exception 'Choose the package again.' using errcode = '23514';
  end if;
  if jsonb_array_length(v_packages) > 20 or jsonb_array_length(v_charges) > 30 then
    raise exception 'Too many lines in this quote.' using errcode = '23514';
  end if;
  if (select count(*) from jsonb_array_elements(v_packages))
     <> (select count(distinct b ->> 'package_id') from jsonb_array_elements(v_packages) b) then
    raise exception 'Each package can be added only once.' using errcode = '23514';
  end if;

  -- All lines with their package, for checks.
  select coalesce(jsonb_agg(l || jsonb_build_object('_pkg', b ->> 'package_id')), '[]'::jsonb)
    into v_all_lines
    from jsonb_array_elements(v_packages) b, jsonb_array_elements(coalesce(b -> 'lines', '[]'::jsonb)) l;

  if jsonb_array_length(v_all_lines) > 300 then
    raise exception 'Too many lines in this quote.' using errcode = '23514';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_packages) b
     where not exists (
       select 1 from jsonb_array_elements(coalesce(b -> 'lines', '[]'::jsonb)) l where coalesce((l ->> 'included')::boolean, true)
     )
  ) then
    raise exception 'Include at least one element.' using errcode = '23514';
  end if;
  if (select count(*) from jsonb_array_elements(v_all_lines))
     <> (select count(distinct (l ->> '_pkg') || ':' || (l ->> 'element_id')) from jsonb_array_elements(v_all_lines) l) then
    raise exception 'Each element can appear only once.' using errcode = '23514';
  end if;

  v_phone := public.normalize_phone(g ->> 'guest_phone');
  if v_phone is null then
    raise exception 'Enter a valid 10-digit mobile number.' using errcode = '23514';
  end if;
  if nullif(g ->> 'event_date', '') is null then
    raise exception 'Choose the event date.' using errcode = '23514';
  end if;

  select name into v_function from public.function_options where id = (g ->> 'function_id')::uuid and owner_id = v_uid;
  select name into v_venue    from public.venues           where id = (g ->> 'venue_id')::uuid    and owner_id = v_uid;
  select name into v_session  from public.sessions         where id = (g ->> 'session_id')::uuid  and owner_id = v_uid;
  if v_function is null or v_venue is null or v_session is null then
    raise exception 'Choose the function, venue and session again.' using errcode = '23514';
  end if;
  if nullif(g ->> 'sub_venue_id', '') is not null then
    select name into v_sub_venue from public.sub_venues
     where id = (g ->> 'sub_venue_id')::uuid and owner_id = v_uid and venue_id = (g ->> 'venue_id')::uuid;
    if v_sub_venue is null then
      raise exception 'The sub-venue does not belong to this venue.' using errcode = '23514';
    end if;
  end if;

  -- Packages must be the caller's.
  select count(*) into v_bad
    from jsonb_array_elements(v_packages) b
    left join public.packages p on p.id = (b ->> 'package_id')::uuid and p.owner_id = v_uid
   where p.id is null;
  if v_bad > 0 then
    raise exception 'Choose the package again.' using errcode = '23514';
  end if;

  select string_agg(p.name, ' + ' order by t.ord), string_agg(tr.name, ' + ' order by t.ord),
         (array_agg(p.id order by t.ord))[1]
    into v_names, v_tiers, v_first_pkg
    from jsonb_array_elements(v_packages) with ordinality as t(b, ord)
    join public.packages p on p.id = (t.b ->> 'package_id')::uuid
    join public.tiers tr on tr.id = p.tier_id;

  -- Elements must be the caller's.
  select count(*) into v_bad
    from jsonb_array_elements(v_all_lines) l
    left join public.elements e on e.id = (l ->> 'element_id')::uuid and e.owner_id = v_uid
   where e.id is null;
  if v_bad > 0 then
    raise exception 'One of the elements is no longer available.' using errcode = '23503';
  end if;

  select coalesce(sum(round((l ->> 'qty')::numeric * (l ->> 'rate')::numeric, 2)), 0)
    into v_subtotal
    from jsonb_array_elements(v_all_lines) l
   where coalesce((l ->> 'included')::boolean, true);
  select coalesce(sum((c ->> 'amount')::numeric), 0) into v_charges_t from jsonb_array_elements(v_charges) c;

  if v_quote_id is null then
    insert into public.quotes (
      owner_id, source, source_ref, source_raw, guest_name, guest_phone, venue_name, sub_venue_name,
      event_date, session_name, function_name, package_id, package_name, package_tier,
      elements_subtotal, charges_total, final_total, notes,
      function_id, venue_id, sub_venue_id, session_id
    ) values (
      v_uid, coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source, nullif(g ->> 'source_ref', ''),
      g -> 'source_raw', btrim(g ->> 'guest_name'), v_phone, v_venue, v_sub_venue,
      (g ->> 'event_date')::date, v_session, v_function, v_first_pkg, v_names, v_tiers,
      v_subtotal, v_charges_t, v_subtotal + v_charges_t, nullif(btrim(coalesce(p_payload ->> 'notes', '')), ''),
      (g ->> 'function_id')::uuid, (g ->> 'venue_id')::uuid, nullif(g ->> 'sub_venue_id', '')::uuid, (g ->> 'session_id')::uuid
    )
    returning id, quote_no into v_quote_id, v_no;
  else
    select status, quote_no into v_status, v_no from public.quotes where id = v_quote_id and owner_id = v_uid for update;
    if v_status is null then
      raise exception 'Quote not found.' using errcode = 'P0002';
    end if;
    if v_status not in ('draft', 'sent') then
      raise exception 'Quote % is % and can no longer be edited.', v_no, v_status using errcode = '23514';
    end if;
    update public.quotes set
      source = coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source,
      source_ref = nullif(g ->> 'source_ref', ''),
      -- Editing from the Studio doesn't carry the original LMS row; keep the stored one.
      source_raw = case when jsonb_typeof(g -> 'source_raw') in ('object', 'array') then g -> 'source_raw' else source_raw end,
      guest_name = btrim(g ->> 'guest_name'), guest_phone = v_phone,
      venue_name = v_venue, sub_venue_name = v_sub_venue, event_date = (g ->> 'event_date')::date,
      session_name = v_session, function_name = v_function,
      package_id = v_first_pkg, package_name = v_names, package_tier = v_tiers,
      elements_subtotal = v_subtotal, charges_total = v_charges_t, final_total = v_subtotal + v_charges_t,
      notes = nullif(btrim(coalesce(p_payload ->> 'notes', '')), ''),
      function_id = (g ->> 'function_id')::uuid, venue_id = (g ->> 'venue_id')::uuid,
      sub_venue_id = nullif(g ->> 'sub_venue_id', '')::uuid, session_id = (g ->> 'session_id')::uuid
    where id = v_quote_id;
    if v_status = 'sent' then
      insert into public.audit_log (owner_id, table_name, row_id, action, old_data, new_data)
      values (v_uid, 'quotes', v_quote_id, 'edited', jsonb_build_object('status', v_status), jsonb_build_object('status', v_status));
    end if;
    delete from public.quote_items where quote_id = v_quote_id;
    delete from public.quote_packages where quote_id = v_quote_id;
    delete from public.quote_charges where quote_id = v_quote_id;
  end if;

  -- One section per package, then its lines.
  for v_block in
    select t.b, t.ord, p.id as pid, p.name as pname, tr.name as ptier
      from jsonb_array_elements(v_packages) with ordinality as t(b, ord)
      join public.packages p on p.id = (t.b ->> 'package_id')::uuid
      join public.tiers tr on tr.id = p.tier_id
     order by t.ord
  loop
    insert into public.quote_packages (owner_id, quote_id, package_id, package_name, package_tier, subtotal, sort_order)
    values (
      v_uid, v_quote_id, v_block.pid, v_block.pname, v_block.ptier,
      (select coalesce(sum(round((l ->> 'qty')::numeric * (l ->> 'rate')::numeric, 2)), 0)
         from jsonb_array_elements(coalesce(v_block.b -> 'lines', '[]'::jsonb)) l
        where coalesce((l ->> 'included')::boolean, true)),
      v_block.ord::integer
    )
    returning id into v_qp_id;

    insert into public.quote_items (
      owner_id, quote_id, quote_package_id, element_id, element_name, unit, image_path, master_rate_at_quote,
      qty, rate, amount, is_included, sort_order
    )
    select v_uid, v_quote_id, v_qp_id, e.id, e.name, e.unit, e.image_path, e.default_rate,
           (t.l ->> 'qty')::numeric, (t.l ->> 'rate')::numeric,
           round((t.l ->> 'qty')::numeric * (t.l ->> 'rate')::numeric, 2),
           coalesce((t.l ->> 'included')::boolean, true), (v_block.ord * 1000 + t.ord)::integer
      from jsonb_array_elements(coalesce(v_block.b -> 'lines', '[]'::jsonb)) with ordinality as t(l, ord)
      join public.elements e on e.id = (t.l ->> 'element_id')::uuid and e.owner_id = v_uid;
  end loop;

  insert into public.quote_charges (owner_id, quote_id, description, amount, sort_order)
  select v_uid, v_quote_id, btrim(t.c ->> 'description'), (t.c ->> 'amount')::numeric, t.ord::integer
    from jsonb_array_elements(v_charges) with ordinality as t(c, ord);

  -- Quote-specific rate overrides -> Rate History (each element+rate logged once per quote).
  insert into public.rate_change_logs (owner_id, change_type, element_id, element_name, quote_id, old_rate, new_rate, reason, changed_by)
  select distinct on (qi.element_id, qi.rate)
         v_uid, 'quote_override', qi.element_id, qi.element_name, v_quote_id, qi.master_rate_at_quote, qi.rate,
         'Rate changed for quote ' || v_no, v_uid
    from public.quote_items qi
   where qi.quote_id = v_quote_id
     and qi.is_included
     and qi.rate is distinct from qi.master_rate_at_quote
     and not exists (
       select 1 from public.rate_change_logs r
        where r.quote_id = v_quote_id and r.element_id = qi.element_id
          and r.change_type = 'quote_override' and r.new_rate = qi.rate
     );

  return jsonb_build_object('id', v_quote_id, 'quote_no', v_no);
end;
$$;
revoke all on function public.save_quote(jsonb) from public, anon;
grant execute on function public.save_quote(jsonb) to authenticated;

-- >>>>>>>>>> 0017_remove_sent.sql
-- =============================================================================
-- 0017_remove_sent.sql — the "Sent" status and "Mark as sent" are removed.
-- Quotes are shared by downloading the PDF / Excel instead.
--
-- * Status flow is now: draft → confirmed | cancelled, confirmed → cancelled.
-- * Quotes that were 'sent' become 'draft' (editable again). No audit rows are written
--   for this clean-up — it isn't a real status change by the user.
-- * 'sent' can't be set any more (check constraint; enum values can't be dropped in place).
-- * mark_quote_sent() and the sent_count / last_sent_at columns are dropped.
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.quotes disable trigger quotes_before_update;
alter table public.quotes disable trigger quotes_audit_status;
update public.quotes set status = 'draft' where status = 'sent';
alter table public.quotes enable trigger quotes_before_update;
alter table public.quotes enable trigger quotes_audit_status;

alter table public.quotes drop constraint if exists quotes_status_no_sent;
alter table public.quotes add constraint quotes_status_no_sent check (status <> 'sent');

drop function if exists public.mark_quote_sent(uuid);
alter table public.quotes drop column if exists sent_count;
alter table public.quotes drop column if exists last_sent_at;

create or replace function public.quotes_before_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id <> old.owner_id or new.quote_no <> old.quote_no then
    raise exception 'owner and quote number cannot change';
  end if;

  if old.status in ('confirmed', 'cancelled') then
    -- package_id may be cleared when the package is deleted; the snapshot stays.
    if (to_jsonb(new) - array['status', 'notes', 'updated_at', 'package_id'])
       <> (to_jsonb(old) - array['status', 'notes', 'updated_at', 'package_id'])
       or (new.package_id is not null and new.package_id is distinct from old.package_id) then
      raise exception 'Quote % is % and can no longer be edited.', old.quote_no, old.status;
    end if;
  end if;

  if new.status <> old.status and not (
       (old.status = 'draft' and new.status in ('confirmed', 'cancelled'))
    or (old.status = 'confirmed' and new.status = 'cancelled')
  ) then
    raise exception 'Invalid status change: % -> %', old.status, new.status;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

-- >>>>>>>>>> 0018_charge_rates.sql
-- =============================================================================
-- 0018_charge_rates.sql — master rates for Additional charges (per user).
--
-- The Studio pre-adds these charges to every new quote:
--   * fixed        → amount = rate                         (Transportation)
--   * per_package  → amount = rate × qty_per_package × number of packages
--                    (Labour: 2 labour per package × ₹500)
-- Staff can still change the amount on a quote ("Adjust rates") or remove the line.
-- The quote keeps only description + amount (snapshot), so changing a rate here never
-- changes saved quotes.
--
-- Defaults for every user: Transportation ₹0 (set it in My Workspace → Settings —
-- it is only added once above ₹0) and Labour 2 per package × ₹500.
-- Safe to re-run (idempotent).
-- =============================================================================

create table if not exists public.charge_rates (
  id              uuid primary key default gen_random_uuid(),
  owner_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  code            text not null check (code ~ '^[a-z_]{2,40}$'),
  label           text not null check (length(btrim(label)) between 1 and 60),
  mode            text not null check (mode in ('fixed', 'per_package')),
  rate            numeric(12, 2) not null default 0 check (rate >= 0 and rate <= 100000000),
  qty_per_package numeric(10, 2) not null default 1 check (qty_per_package > 0 and qty_per_package <= 10000),
  auto_add        boolean not null default true,
  sort_order      integer not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (owner_id, code)
);

drop trigger if exists set_updated_at on public.charge_rates;
create trigger set_updated_at before update on public.charge_rates
  for each row execute function public.set_updated_at();

drop trigger if exists charge_rates_rate_limit on public.charge_rates;
create trigger charge_rates_rate_limit before insert or update on public.charge_rates
  for each row execute function public.rate_limit_writes('charge_rates_write', '60', '60');

-- Owner and code never change (the Studio links quote lines to the code).
create or replace function public.charge_rates_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id <> old.owner_id or new.code <> old.code or new.mode <> old.mode then
    raise exception 'owner, code and mode of a charge rate cannot change';
  end if;
  return new;
end;
$$;

drop trigger if exists charge_rates_guard on public.charge_rates;
create trigger charge_rates_guard before update on public.charge_rates
  for each row execute function public.charge_rates_guard();

-- Read + edit own rows only (the defaults are seeded; no insert/delete from the app).
alter table public.charge_rates enable row level security;
revoke all on public.charge_rates from anon, authenticated;
grant select, update on public.charge_rates to authenticated;
drop policy if exists own_select on public.charge_rates;
drop policy if exists own_update on public.charge_rates;
create policy own_select on public.charge_rates for select to authenticated using (owner_id = (select auth.uid()));
create policy own_update on public.charge_rates for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

-- ---------- Defaults --------------------------------------------------------
create or replace function public.seed_default_charge_rates(p_owner uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.charge_rates (owner_id, code, label, mode, rate, qty_per_package, sort_order)
  values
    (p_owner, 'transportation', 'Transportation', 'fixed', 0, 1, 1),
    (p_owner, 'labour', 'Labour', 'per_package', 500, 2, 2)
  on conflict (owner_id, code) do nothing;
end;
$$;

revoke all on function public.seed_default_charge_rates(uuid) from public, anon, authenticated;

-- New users get them too (same body as 0003 plus the charge rates).
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text;
begin
  v_phone := coalesce(
    public.normalize_phone(new.phone),
    case when new.email ilike '%@phone.invalid' then public.normalize_phone(split_part(new.email, '@', 1)) end
  );

  insert into public.profiles (id, phone, full_name, must_change_password)
  values (new.id, v_phone, nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''), true)
  on conflict (id) do nothing;

  perform public.seed_default_options(new.id);
  perform public.seed_default_charge_rates(new.id);
  return new;
end;
$$;

revoke all on function public.handle_new_user() from public, anon, authenticated;

-- Existing users.
select public.seed_default_charge_rates(p.id) from public.profiles p;

-- >>>>>>>>>> 0019_charge_venue_rates.sql
-- =============================================================================
-- 0019_charge_venue_rates.sql — Additional charge rates per venue.
--
-- A venue row overrides the default rate in charge_rates for quotes at that venue
-- (e.g. Transportation ₹2,000 at Exotica, ₹3,500 at Pushpanjali). For Labour the venue
-- row can also override "labour per package" (null = use the default).
-- No row for a venue → the default applies. A venue rate of ₹0 = not charged there.
--
-- save_charge_rate(...) saves the default and every venue row in one transaction.
-- Safe to re-run (idempotent).
-- =============================================================================

-- Composite FK target so venue rows can only point at the owner's own charge rate.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'charge_rates_owner_id_id_key') then
    alter table public.charge_rates add constraint charge_rates_owner_id_id_key unique (owner_id, id);
  end if;
end $$;

create table if not exists public.charge_venue_rates (
  id              uuid primary key default gen_random_uuid(),
  owner_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  charge_rate_id  uuid not null,
  venue_id        uuid not null,
  rate            numeric(12, 2) not null check (rate >= 0 and rate <= 100000000),
  qty_per_package numeric(10, 2) check (qty_per_package is null or (qty_per_package > 0 and qty_per_package <= 10000)),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (owner_id, charge_rate_id, venue_id),
  constraint charge_venue_rates_charge_fkey foreign key (owner_id, charge_rate_id)
    references public.charge_rates (owner_id, id) on delete cascade,
  constraint charge_venue_rates_venue_fkey foreign key (owner_id, venue_id)
    references public.venues (owner_id, id) on delete cascade
);

drop trigger if exists set_updated_at on public.charge_venue_rates;
create trigger set_updated_at before update on public.charge_venue_rates
  for each row execute function public.set_updated_at();

drop trigger if exists charge_venue_rates_rate_limit on public.charge_venue_rates;
create trigger charge_venue_rates_rate_limit before insert or update on public.charge_venue_rates
  for each row execute function public.rate_limit_writes('charge_rates_write', '120', '60');

alter table public.charge_venue_rates enable row level security;
revoke all on public.charge_venue_rates from anon, authenticated;
grant select, insert, update, delete on public.charge_venue_rates to authenticated;
drop policy if exists own_select on public.charge_venue_rates;
drop policy if exists own_insert on public.charge_venue_rates;
drop policy if exists own_update on public.charge_venue_rates;
drop policy if exists own_delete on public.charge_venue_rates;
create policy own_select on public.charge_venue_rates for select to authenticated using (owner_id = (select auth.uid()));
create policy own_insert on public.charge_venue_rates for insert to authenticated with check (owner_id = (select auth.uid()));
create policy own_update on public.charge_venue_rates for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy own_delete on public.charge_venue_rates for delete to authenticated using (owner_id = (select auth.uid()));

-- ---------- Save a charge's default + venue rates in one go -------------------
-- p_venues: [{ "venue_id": uuid, "rate": number, "qty_per_package": number|null }, ...]
-- Venues left out of the list go back to the default. Runs as the caller (RLS applies).
create or replace function public.save_charge_rate(
  p_id              uuid,
  p_rate            numeric,
  p_qty_per_package numeric,
  p_venues          jsonb
)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if jsonb_typeof(coalesce(p_venues, '[]'::jsonb)) <> 'array' then
    raise exception 'p_venues must be an array' using errcode = '22023';
  end if;

  update public.charge_rates
     set rate = p_rate,
         qty_per_package = coalesce(p_qty_per_package, qty_per_package)
   where id = p_id;
  if not found then
    raise exception 'Charge rate not found' using errcode = 'P0002';
  end if;

  delete from public.charge_venue_rates where charge_rate_id = p_id;

  insert into public.charge_venue_rates (charge_rate_id, venue_id, rate, qty_per_package)
  select p_id, (v ->> 'venue_id')::uuid, (v ->> 'rate')::numeric, nullif(v ->> 'qty_per_package', '')::numeric
  from jsonb_array_elements(coalesce(p_venues, '[]'::jsonb)) v;
end;
$$;

revoke all on function public.save_charge_rate(uuid, numeric, numeric, jsonb) from public, anon;
grant execute on function public.save_charge_rate(uuid, numeric, numeric, jsonb) to authenticated;

-- >>>>>>>>>> 0020_manaktala_venue.sql
-- =============================================================================
-- 0020_manaktala_venue.sql — the "Emerald Green" venue is shown as "Manaktala".
--
-- It is the same LMS venue (id 6, "Manaktala Farm"), so it is renamed in place: the LMS
-- link, venue charge rates and sub-venues stay. Saved quotes keep the venue name they
-- were saved with. New users get "Manaktala" from the start.
-- Safe to re-run (idempotent).
-- =============================================================================

update public.venues v
   set name = 'Manaktala'
 where lower(v.name) = 'emerald green'
   and not exists (
     select 1 from public.venues m where m.owner_id = v.owner_id and lower(m.name) = 'manaktala'
   );

-- Defaults for new users (same as 0002, with the new name).
create or replace function public.seed_default_options(p_owner uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
