-- >>>>>>>>>> 0021_element_remarks.sql
-- =============================================================================
-- 0021_element_remarks.sql — internal remarks on an element (where it is used, e.g.
-- "Entrance gate, Exotica lawn"). Workspace only; never sent to the Guest Studio.
-- update_element gains p_remarks (the old 8-argument version is replaced).
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.elements add column if not exists remarks text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'elements_remarks_len') then
    alter table public.elements add constraint elements_remarks_len check (remarks is null or length(remarks) <= 500);
  end if;
end $$;

drop function if exists public.update_element(uuid, text, text, numeric, numeric, text, numeric, text);

create or replace function public.update_element(
  p_id           uuid,
  p_name         text,
  p_unit         text,
  p_default_rate numeric,
  p_default_qty  numeric,
  p_image_path   text,
  p_unit_cost    numeric,
  p_reason       text default null,
  p_remarks      text default null
)
returns public.elements
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v public.elements;
begin
  if p_reason is not null and length(p_reason) > 500 then
    raise exception 'Reason must be 500 characters or fewer.' using errcode = '23514';
  end if;
  perform set_config('app.rate_change_reason', coalesce(p_reason, ''), true);
  update public.elements
     set name         = btrim(p_name),
         unit         = nullif(btrim(coalesce(p_unit, '')), ''),
         default_rate = p_default_rate,
         default_qty  = p_default_qty,
         image_path   = p_image_path,
         unit_cost    = p_unit_cost,
         remarks      = nullif(btrim(coalesce(p_remarks, '')), '')
   where id = p_id
  returning * into v;
  perform set_config('app.rate_change_reason', '', true);
  if v.id is null then
    raise exception 'Element not found.' using errcode = 'P0002';
  end if;
  return v;
end;
$$;
revoke all on function public.update_element(uuid, text, text, numeric, numeric, text, numeric, text, text) from public, anon;
grant execute on function public.update_element(uuid, text, text, numeric, numeric, text, numeric, text, text) to authenticated;

-- >>>>>>>>>> 0022_quote_item_remarks.sql
-- =============================================================================
-- 0022_quote_item_remarks.sql — element remarks ("where it is used") are now shown to the
-- guest: in the Studio while choosing elements, on the quotation and in the PDF / Excel.
--
-- quote_items.remarks is a snapshot taken when the line is saved (same idea as the name
-- and unit), so editing an element's remarks later doesn't change saved quotes. A draft
-- picks up the current remarks the next time it is saved.
-- Draft quotes saved before this get today's remarks once; confirmed/cancelled quotes stay
-- exactly as they were.
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.quote_items add column if not exists remarks text;

create or replace function public.quote_items_snapshot_remarks()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.element_id is not null and new.remarks is null then
    select e.remarks into new.remarks
      from public.elements e
     where e.id = new.element_id and e.owner_id = new.owner_id;
  end if;
  return new;
end;
$$;

drop trigger if exists quote_items_snapshot_remarks on public.quote_items;
create trigger quote_items_snapshot_remarks before insert on public.quote_items
  for each row execute function public.quote_items_snapshot_remarks();

-- Drafts only (the guard trigger keeps confirmed/cancelled lines frozen anyway).
update public.quote_items qi
   set remarks = e.remarks
  from public.elements e, public.quotes q
 where qi.remarks is null
   and e.id = qi.element_id and e.owner_id = qi.owner_id and e.remarks is not null
   and q.id = qi.quote_id and q.status = 'draft';

-- >>>>>>>>>> 0023_element_multiplier.sql
-- =============================================================================
-- 0023_element_multiplier.sql — a multiplier on each element (My Workspace only).
--
--   guest rate (selling_rate) = default_rate × multiplier
-- The Guest Studio only ever reads selling_rate, so the multiplier is never shown or sent
-- to the guest side. Quotes store the rate used (as before), package totals and the
-- "rate changed for this quote" check use selling_rate.
--
-- An earlier draft of this migration put the multiplier on quote lines; that column is
-- removed here if it exists. Safe to re-run (idempotent).
-- =============================================================================

alter table public.quote_items drop constraint if exists quote_items_multiplier_range;
alter table public.quote_items drop column if exists multiplier;

alter table public.elements add column if not exists multiplier numeric(10, 2) not null default 1;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'elements_multiplier_range') then
    alter table public.elements add constraint elements_multiplier_range check (multiplier > 0 and multiplier <= 10000);
  end if;
end $$;

alter table public.elements
  add column if not exists selling_rate numeric(12, 2) generated always as (round(default_rate * multiplier, 2)) stored;

-- ---------- update_element gains p_multiplier (null = keep) ------------------------
drop function if exists public.update_element(uuid, text, text, numeric, numeric, text, numeric, text, text);

create or replace function public.update_element(
  p_id           uuid,
  p_name         text,
  p_unit         text,
  p_default_rate numeric,
  p_default_qty  numeric,
  p_image_path   text,
  p_unit_cost    numeric,
  p_reason       text default null,
  p_remarks      text default null,
  p_multiplier   numeric default null
)
returns public.elements
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v public.elements;
begin
  if p_reason is not null and length(p_reason) > 500 then
    raise exception 'Reason must be 500 characters or fewer.' using errcode = '23514';
  end if;
  perform set_config('app.rate_change_reason', coalesce(p_reason, ''), true);
  update public.elements
     set name         = btrim(p_name),
         unit         = nullif(btrim(coalesce(p_unit, '')), ''),
         default_rate = p_default_rate,
         default_qty  = p_default_qty,
         image_path   = p_image_path,
         unit_cost    = p_unit_cost,
         remarks      = nullif(btrim(coalesce(p_remarks, '')), ''),
         multiplier   = coalesce(p_multiplier, multiplier)
   where id = p_id
  returning * into v;
  perform set_config('app.rate_change_reason', '', true);
  if v.id is null then
    raise exception 'Element not found.' using errcode = 'P0002';
  end if;
  return v;
end;
$$;
revoke all on function public.update_element(uuid, text, text, numeric, numeric, text, numeric, text, text, numeric) from public, anon;
