-- ---------- Package totals use the guest rate --------------------------------------
create or replace view public.package_summaries
with (security_invoker = true) as
select
  p.id,
  p.owner_id,
  p.name,
  p.tier_id,
  t.name       as tier_name,
  t.sort_order as tier_sort,
  p.display_price,
  p.description,
  p.image_path,
  p.video_url,
  p.is_active,
  p.created_at,
  p.updated_at,
  count(pe.id)::integer as element_count,
  coalesce(sum(round(pe.default_qty * e.selling_rate, 2)), 0)::numeric(14, 2) as elements_total
from public.packages p
join public.tiers t on t.id = p.tier_id
left join public.package_elements pe on pe.package_id = p.id
left join public.elements e on e.id = pe.element_id
group by p.id, t.id;

revoke all on public.package_summaries from anon, authenticated;
grant select on public.package_summaries to authenticated;

-- ---------- save_quote: 0016 version, master rate = selling_rate ---------------------
create or replace function public.save_quote(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := auth.uid();
  v_quote_id  uuid := nullif(p_payload ->> 'quote_id', '')::uuid;
  g           jsonb := p_payload -> 'guest';
  v_packages  jsonb;
  v_charges   jsonb := coalesce(p_payload -> 'charges', '[]'::jsonb);
  v_all_lines jsonb;
  v_phone     text;
  v_function  text;
  v_venue     text;
  v_sub_venue text;
  v_session   text;
  v_names     text;
  v_tiers     text;
  v_first_pkg uuid;
  v_subtotal  numeric(14, 2);
  v_charges_t numeric(14, 2);
  v_status    public.quote_status;
  v_no        text;
  v_bad       integer;
  v_block     record;
  v_qp_id     uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform public.enforce_rate_limit('quote_save', 20, 60);

  -- Old single-package payload -> one block.
  v_packages := coalesce(
    p_payload -> 'packages',
    case when p_payload ? 'package_id'
         then jsonb_build_array(jsonb_build_object('package_id', p_payload -> 'package_id', 'lines', coalesce(p_payload -> 'lines', '[]'::jsonb)))
    end,
    '[]'::jsonb
  );

  if g is null or jsonb_typeof(g) <> 'object' then
    raise exception 'Guest details are missing.' using errcode = '23514';
  end if;
  if jsonb_typeof(v_packages) <> 'array' or jsonb_typeof(v_charges) <> 'array' then
    raise exception 'Invalid quote payload.' using errcode = '22023';
  end if;
  if jsonb_array_length(v_packages) = 0 then
    raise exception 'Choose the package again.' using errcode = '23514';
  end if;
  if jsonb_array_length(v_packages) > 20 or jsonb_array_length(v_charges) > 30 then
    raise exception 'Too many lines in this quote.' using errcode = '23514';
  end if;
  if (select count(*) from jsonb_array_elements(v_packages))
     <> (select count(distinct b ->> 'package_id') from jsonb_array_elements(v_packages) b) then
    raise exception 'Each package can be added only once.' using errcode = '23514';
  end if;

  -- All lines with their package, for checks.
  select coalesce(jsonb_agg(l || jsonb_build_object('_pkg', b ->> 'package_id')), '[]'::jsonb)
    into v_all_lines
    from jsonb_array_elements(v_packages) b, jsonb_array_elements(coalesce(b -> 'lines', '[]'::jsonb)) l;

  if jsonb_array_length(v_all_lines) > 300 then
    raise exception 'Too many lines in this quote.' using errcode = '23514';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_packages) b
     where not exists (
       select 1 from jsonb_array_elements(coalesce(b -> 'lines', '[]'::jsonb)) l where coalesce((l ->> 'included')::boolean, true)
     )
  ) then
    raise exception 'Include at least one element.' using errcode = '23514';
  end if;
  if (select count(*) from jsonb_array_elements(v_all_lines))
     <> (select count(distinct (l ->> '_pkg') || ':' || (l ->> 'element_id')) from jsonb_array_elements(v_all_lines) l) then
    raise exception 'Each element can appear only once.' using errcode = '23514';
  end if;

  v_phone := public.normalize_phone(g ->> 'guest_phone');
  if v_phone is null then
    raise exception 'Enter a valid 10-digit mobile number.' using errcode = '23514';
  end if;
  if nullif(g ->> 'event_date', '') is null then
    raise exception 'Choose the event date.' using errcode = '23514';
  end if;

  select name into v_function from public.function_options where id = (g ->> 'function_id')::uuid and owner_id = v_uid;
  select name into v_venue    from public.venues           where id = (g ->> 'venue_id')::uuid    and owner_id = v_uid;
  select name into v_session  from public.sessions         where id = (g ->> 'session_id')::uuid  and owner_id = v_uid;
  if v_function is null or v_venue is null or v_session is null then
    raise exception 'Choose the function, venue and session again.' using errcode = '23514';
  end if;
  if nullif(g ->> 'sub_venue_id', '') is not null then
    select name into v_sub_venue from public.sub_venues
     where id = (g ->> 'sub_venue_id')::uuid and owner_id = v_uid and venue_id = (g ->> 'venue_id')::uuid;
    if v_sub_venue is null then
      raise exception 'The sub-venue does not belong to this venue.' using errcode = '23514';
    end if;
  end if;

  -- Packages must be the caller's.
  select count(*) into v_bad
    from jsonb_array_elements(v_packages) b
    left join public.packages p on p.id = (b ->> 'package_id')::uuid and p.owner_id = v_uid
   where p.id is null;
  if v_bad > 0 then
    raise exception 'Choose the package again.' using errcode = '23514';
  end if;

  select string_agg(p.name, ' + ' order by t.ord), string_agg(tr.name, ' + ' order by t.ord),
         (array_agg(p.id order by t.ord))[1]
    into v_names, v_tiers, v_first_pkg
    from jsonb_array_elements(v_packages) with ordinality as t(b, ord)
    join public.packages p on p.id = (t.b ->> 'package_id')::uuid
    join public.tiers tr on tr.id = p.tier_id;

  -- Elements must be the caller's.
  select count(*) into v_bad
    from jsonb_array_elements(v_all_lines) l
    left join public.elements e on e.id = (l ->> 'element_id')::uuid and e.owner_id = v_uid
   where e.id is null;
  if v_bad > 0 then
    raise exception 'One of the elements is no longer available.' using errcode = '23503';
  end if;

  select coalesce(sum(round((l ->> 'qty')::numeric * (l ->> 'rate')::numeric, 2)), 0)
    into v_subtotal
    from jsonb_array_elements(v_all_lines) l
   where coalesce((l ->> 'included')::boolean, true);
  select coalesce(sum((c ->> 'amount')::numeric), 0) into v_charges_t from jsonb_array_elements(v_charges) c;

  if v_quote_id is null then
    insert into public.quotes (
      owner_id, source, source_ref, source_raw, guest_name, guest_phone, venue_name, sub_venue_name,
      event_date, session_name, function_name, package_id, package_name, package_tier,
      elements_subtotal, charges_total, final_total, notes,
      function_id, venue_id, sub_venue_id, session_id
    ) values (
      v_uid, coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source, nullif(g ->> 'source_ref', ''),
      g -> 'source_raw', btrim(g ->> 'guest_name'), v_phone, v_venue, v_sub_venue,
      (g ->> 'event_date')::date, v_session, v_function, v_first_pkg, v_names, v_tiers,
      v_subtotal, v_charges_t, v_subtotal + v_charges_t, nullif(btrim(coalesce(p_payload ->> 'notes', '')), ''),
      (g ->> 'function_id')::uuid, (g ->> 'venue_id')::uuid, nullif(g ->> 'sub_venue_id', '')::uuid, (g ->> 'session_id')::uuid
    )
    returning id, quote_no into v_quote_id, v_no;
  else
    select status, quote_no into v_status, v_no from public.quotes where id = v_quote_id and owner_id = v_uid for update;
    if v_status is null then
      raise exception 'Quote not found.' using errcode = 'P0002';
    end if;
    if v_status not in ('draft', 'sent') then
      raise exception 'Quote % is % and can no longer be edited.', v_no, v_status using errcode = '23514';
    end if;
    update public.quotes set
      source = coalesce(nullif(g ->> 'source', ''), 'manual')::public.quote_source,
      source_ref = nullif(g ->> 'source_ref', ''),
      -- Editing from the Studio doesn't carry the original LMS row; keep the stored one.
      source_raw = case when jsonb_typeof(g -> 'source_raw') in ('object', 'array') then g -> 'source_raw' else source_raw end,
      guest_name = btrim(g ->> 'guest_name'), guest_phone = v_phone,
      venue_name = v_venue, sub_venue_name = v_sub_venue, event_date = (g ->> 'event_date')::date,
      session_name = v_session, function_name = v_function,
      package_id = v_first_pkg, package_name = v_names, package_tier = v_tiers,
      elements_subtotal = v_subtotal, charges_total = v_charges_t, final_total = v_subtotal + v_charges_t,
      notes = nullif(btrim(coalesce(p_payload ->> 'notes', '')), ''),
      function_id = (g ->> 'function_id')::uuid, venue_id = (g ->> 'venue_id')::uuid,
      sub_venue_id = nullif(g ->> 'sub_venue_id', '')::uuid, session_id = (g ->> 'session_id')::uuid
    where id = v_quote_id;
    if v_status = 'sent' then
      insert into public.audit_log (owner_id, table_name, row_id, action, old_data, new_data)
      values (v_uid, 'quotes', v_quote_id, 'edited', jsonb_build_object('status', v_status), jsonb_build_object('status', v_status));
    end if;
    delete from public.quote_items where quote_id = v_quote_id;
    delete from public.quote_packages where quote_id = v_quote_id;
    delete from public.quote_charges where quote_id = v_quote_id;
  end if;

  -- One section per package, then its lines.
  for v_block in
    select t.b, t.ord, p.id as pid, p.name as pname, tr.name as ptier
      from jsonb_array_elements(v_packages) with ordinality as t(b, ord)
      join public.packages p on p.id = (t.b ->> 'package_id')::uuid
      join public.tiers tr on tr.id = p.tier_id
     order by t.ord
  loop
    insert into public.quote_packages (owner_id, quote_id, package_id, package_name, package_tier, subtotal, sort_order)
    values (
      v_uid, v_quote_id, v_block.pid, v_block.pname, v_block.ptier,
      (select coalesce(sum(round((l ->> 'qty')::numeric * (l ->> 'rate')::numeric, 2)), 0)
         from jsonb_array_elements(coalesce(v_block.b -> 'lines', '[]'::jsonb)) l
        where coalesce((l ->> 'included')::boolean, true)),
      v_block.ord::integer
    )
    returning id into v_qp_id;

    insert into public.quote_items (
      owner_id, quote_id, quote_package_id, element_id, element_name, unit, image_path, master_rate_at_quote,
      qty, rate, amount, is_included, sort_order
    )
    select v_uid, v_quote_id, v_qp_id, e.id, e.name, e.unit, e.image_path, e.selling_rate,
           (t.l ->> 'qty')::numeric, (t.l ->> 'rate')::numeric,
           round((t.l ->> 'qty')::numeric * (t.l ->> 'rate')::numeric, 2),
           coalesce((t.l ->> 'included')::boolean, true), (v_block.ord * 1000 + t.ord)::integer
      from jsonb_array_elements(coalesce(v_block.b -> 'lines', '[]'::jsonb)) with ordinality as t(l, ord)
      join public.elements e on e.id = (t.l ->> 'element_id')::uuid and e.owner_id = v_uid;
  end loop;

  insert into public.quote_charges (owner_id, quote_id, description, amount, sort_order)
  select v_uid, v_quote_id, btrim(t.c ->> 'description'), (t.c ->> 'amount')::numeric, t.ord::integer
    from jsonb_array_elements(v_charges) with ordinality as t(c, ord);

  -- Quote-specific rate overrides -> Rate History (each element+rate logged once per quote).
  insert into public.rate_change_logs (owner_id, change_type, element_id, element_name, quote_id, old_rate, new_rate, reason, changed_by)
  select distinct on (qi.element_id, qi.rate)
         v_uid, 'quote_override', qi.element_id, qi.element_name, v_quote_id, qi.master_rate_at_quote, qi.rate,
         'Rate changed for quote ' || v_no, v_uid
    from public.quote_items qi
   where qi.quote_id = v_quote_id
     and qi.is_included
     and qi.rate is distinct from qi.master_rate_at_quote
     and not exists (
       select 1 from public.rate_change_logs r
        where r.quote_id = v_quote_id and r.element_id = qi.element_id
          and r.change_type = 'quote_override' and r.new_rate = qi.rate
     );

  return jsonb_build_object('id', v_quote_id, 'quote_no', v_no);
end;
$$;
revoke all on function public.save_quote(jsonb) from public, anon;
grant execute on function public.save_quote(jsonb) to authenticated;

-- >>>>>>>>>> 0024_package_functions.sql
-- =============================================================================
-- 0024_package_functions.sql — which functions a package is meant for (optional).
--
-- * A package can be tagged with one or more functions (Wedding, Sangeet…), or none.
--   No function = usable for any function.
-- * The Guest Studio still shows EVERY active package — never hidden by function — but
--   packages tagged with the guest's function come first; everything else follows under
--   "Other packages" (studio_packages RPC, server-paginated).
-- * set_package_functions replaces a package's functions in one call.
-- Safe to re-run (idempotent).
-- =============================================================================

create table if not exists public.package_functions (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  package_id  uuid not null,
  function_id uuid not null,
  created_at  timestamptz not null default now(),
  unique (owner_id, package_id, function_id),
  constraint package_functions_package_fkey foreign key (owner_id, package_id)
    references public.packages (owner_id, id) on delete cascade,
  constraint package_functions_function_fkey foreign key (owner_id, function_id)
    references public.function_options (owner_id, id) on delete cascade
);
create index if not exists package_functions_function_idx on public.package_functions (owner_id, function_id);

drop trigger if exists package_functions_rate_limit on public.package_functions;
create trigger package_functions_rate_limit before insert on public.package_functions
  for each row execute function public.rate_limit_writes('package_functions_write', '300', '60');

alter table public.package_functions enable row level security;
revoke all on public.package_functions from anon, authenticated;
grant select, insert, delete on public.package_functions to authenticated;
drop policy if exists own_select on public.package_functions;
drop policy if exists own_insert on public.package_functions;
drop policy if exists own_delete on public.package_functions;
create policy own_select on public.package_functions for select to authenticated using (owner_id = (select auth.uid()));
create policy own_insert on public.package_functions for insert to authenticated with check (owner_id = (select auth.uid()));
create policy own_delete on public.package_functions for delete to authenticated using (owner_id = (select auth.uid()));

-- ---------- Replace a package's functions ----------------------------------------
create or replace function public.set_package_functions(p_package_id uuid, p_function_ids uuid[])
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if not exists (select 1 from public.packages where id = p_package_id) then
    raise exception 'Package not found.' using errcode = 'P0002';
  end if;
  if coalesce(array_length(p_function_ids, 1), 0) > 50 then
    raise exception 'Too many functions.' using errcode = '23514';
  end if;
  delete from public.package_functions where package_id = p_package_id;
  insert into public.package_functions (package_id, function_id)
  select distinct p_package_id, f from unnest(coalesce(p_function_ids, '{}'::uuid[])) f;
end;
$$;
revoke all on function public.set_package_functions(uuid, uuid[]) from public, anon;
grant execute on function public.set_package_functions(uuid, uuid[]) to authenticated;

-- ---------- Guest Studio list: the guest's function first, then the rest ----------
-- Guest-safe columns only. for_function = tagged with p_function_id. total = all active.
create or replace function public.studio_packages(p_function_id uuid, p_offset integer, p_limit integer)
returns table (
  id            uuid,
  name          text,
  tier_name     text,
  display_price numeric,
  description   text,
  image_path    text,
  video_url     text,
  for_function  boolean,
  total         bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select s.id, s.name, s.tier_name, s.display_price, s.description, s.image_path, s.video_url,
         (p_function_id is not null and exists (
            select 1 from public.package_functions pf where pf.package_id = s.id and pf.function_id = p_function_id
         )) as for_function,
         count(*) over () as total
    from public.package_summaries s
   where s.is_active
   order by for_function desc, s.name, s.tier_sort, s.id
  offset greatest(coalesce(p_offset, 0), 0)
   limit least(greatest(coalesce(p_limit, 12), 1), 50);
$$;
revoke all on function public.studio_packages(uuid, integer, integer) from public, anon;
grant execute on function public.studio_packages(uuid, integer, integer) to authenticated;

-- >>>>>>>>>> 0025_fill_missing_costs.sql
-- =============================================================================
-- 0025_fill_missing_costs.sql — quote lines with a MISSING cost pick it up later.
--
-- A quote line's cost is locked when the quote is saved. If the element had no cost then
-- (no unit cost, no vendor rate), the line stays "Cost missing" and the quote is left out
-- of the P&L totals. Now:
--   * setting an element's unit cost, or logging a vendor rate for it, fills its missing
--     lines straight away (all quotes, any status — only the internal cost is written;
--     the guest's rate, amount and totals never change);
--   * every missing line today is filled once by this migration.
-- A cost that is already locked is never changed.
-- Vendor rates count if bought on or before the event date (or today if there is none).
-- Safe to re-run (idempotent).
-- =============================================================================

-- ---------- Guard: allow filling a missing cost on frozen quotes ---------------------
create or replace function public.quote_children_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_status public.quote_status;
  v_quote  uuid := coalesce(new.quote_id, old.quote_id);
  v_keys   text[] := array['element_id', 'package_id', 'unit_cost_at_quote', 'cost_source'];
begin
  if tg_op = 'UPDATE' and (to_jsonb(new) - v_keys) = (to_jsonb(old) - v_keys) then
    -- Element/package links cleared by ON DELETE SET NULL; snapshots untouched.
    if (to_jsonb(new) -> 'unit_cost_at_quote') is not distinct from (to_jsonb(old) -> 'unit_cost_at_quote')
       and (to_jsonb(new) -> 'cost_source') is not distinct from (to_jsonb(old) -> 'cost_source') then
      return new;
    end if;
    -- Filling a cost that was missing (internal only — the guest's numbers don't change).
    if (to_jsonb(old) ->> 'unit_cost_at_quote') is null then
      return new;
    end if;
  end if;
  select status into v_status from public.quotes where id = v_quote;
  if v_status in ('confirmed', 'cancelled') then
    raise exception 'Quote is % — its lines are frozen.', v_status;
  end if;
  return coalesce(new, old);
end;
$$;

-- ---------- Fill missing costs ---------------------------------------------------
create or replace function public.fill_missing_quote_costs(p_owner uuid, p_element_id uuid default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_n     integer;
begin
  update public.quote_items qi
     set unit_cost_at_quote = c.unit_cost, cost_source = c.source
    from (
      select x.id, ec.unit_cost, ec.source
        from public.quote_items x
        join public.quotes q on q.id = x.quote_id
        cross join lateral public.element_cost(x.element_id, least(v_today, coalesce(q.event_date, v_today))) ec
       where x.owner_id = p_owner
         and x.unit_cost_at_quote is null
         and x.element_id is not null
         and (p_element_id is null or x.element_id = p_element_id)
         and ec.unit_cost is not null
    ) c
   where c.id = qi.id;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;
revoke all on function public.fill_missing_quote_costs(uuid, uuid) from public, anon, authenticated;

create or replace function public.elements_fill_missing_costs()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.unit_cost is not null and new.unit_cost is distinct from old.unit_cost then
    perform public.fill_missing_quote_costs(new.owner_id, new.id);
  end if;
  return new;
end;
$$;
revoke all on function public.elements_fill_missing_costs() from public, anon, authenticated;
drop trigger if exists elements_fill_missing_costs on public.elements;
create trigger elements_fill_missing_costs after update of unit_cost on public.elements
  for each row execute function public.elements_fill_missing_costs();

create or replace function public.vendor_rates_fill_missing_costs()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.fill_missing_quote_costs(new.owner_id, new.element_id);
  return new;
end;
$$;
revoke all on function public.vendor_rates_fill_missing_costs() from public, anon, authenticated;
drop trigger if exists vendor_rates_fill_missing_costs on public.vendor_rate_entries;
create trigger vendor_rates_fill_missing_costs after insert on public.vendor_rate_entries
  for each row execute function public.vendor_rates_fill_missing_costs();

-- ---------- Fill what is missing today ---------------------------------------------
select public.fill_missing_quote_costs(p.id) from public.profiles p;

-- >>>>>>>>>> 0026_cost_is_default_rate.sql
-- =============================================================================
-- 0026_cost_is_default_rate.sql — the element's Default rate IS the cost.
--
-- The guest pays rate × multiplier (elements.selling_rate, 0023); the Default rate before
-- the multiplier is what it costs us. So for P&L:
--   cost per unit = elements.default_rate   (cost_source 'base_rate')
-- The separate "unit cost" and vendor purchase rates are no longer used for P&L (vendor
-- rates stay as purchase history). Cost is still locked on each quote line when saved.
--
-- At the user's request every saved quote line is re-costed once from its element's
-- current Default rate (internal only — the guest's rate, amounts and totals don't change).
-- Lines whose element was deleted keep what they had.
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.quote_items drop constraint if exists quote_items_cost_source_check;
alter table public.quote_items add constraint quote_items_cost_source_check
  check (cost_source is null or cost_source in ('fixed', 'vendor', 'base_rate'));

-- Used when a quote line is saved (quote_items_lock_cost) and to fill missing costs.
create or replace function public.element_cost(p_element_id uuid, p_on date)
returns table (unit_cost numeric, source text)
language sql
stable
set search_path = ''
as $$
  select e.default_rate, 'base_rate'::text
    from public.elements e
   where e.id = p_element_id;
$$;

-- The unit cost / vendor rate no longer decide the cost, so these triggers go.
drop trigger if exists elements_fill_missing_costs on public.elements;
drop trigger if exists vendor_rates_fill_missing_costs on public.vendor_rate_entries;

-- Re-cost every saved line once (frozen quotes included — internal cost only).
alter table public.quote_items disable trigger quote_items_guard;
update public.quote_items qi
   set unit_cost_at_quote = e.default_rate, cost_source = 'base_rate'
  from public.elements e
 where e.id = qi.element_id and e.owner_id = qi.owner_id
   and (qi.unit_cost_at_quote is distinct from e.default_rate or qi.cost_source is distinct from 'base_rate');
alter table public.quote_items enable trigger quote_items_guard;

-- >>>>>>>>>> 0027_vendor_rate_latest.sql
-- =============================================================================
-- 0027_vendor_rate_latest.sql — simple "old → new" view of vendor purchase rates.
--
-- One row per element + vendor: the latest purchase (new rate) and the one before it
-- (old rate), how many purchases there are, and whether the rate went up or down.
-- Voided entries are ignored. The full list stays in vendor_rate_history.
-- Safe to re-run (idempotent).
-- =============================================================================

create or replace view public.vendor_rate_latest
with (security_invoker = true) as
with ranked as (
  select
    r.*,
    row_number() over w                          as rn,
    lead(r.rate_per_unit) over w                  as old_rate,
    lead(r.purchase_date) over w                  as old_date,
    count(*) over (partition by r.owner_id, r.element_id, r.vendor_id) as purchases
  from public.vendor_rate_entries r
  where r.voided_at is null
  window w as (partition by r.owner_id, r.element_id, r.vendor_id order by r.purchase_date desc, r.logged_at desc, r.id desc)
)
select
  r.id,
  r.owner_id,
  r.element_id,
  e.name           as element_name,
  r.vendor_id,
  v.name           as vendor_name,
  r.purchase_date  as new_date,
  r.qty,
  r.unit,
  r.rate_per_unit  as new_rate,
  r.old_rate,
  r.old_date,
  r.purchases::integer as purchases,
  case
    when r.old_rate is null then 'new'
    when r.rate_per_unit > r.old_rate then 'up'
    when r.rate_per_unit < r.old_rate then 'down'
    else 'same'
  end as trend
from ranked r
join public.elements e on e.id = r.element_id
join public.vendors v on v.id = r.vendor_id
where r.rn = 1;

revoke all on public.vendor_rate_latest from anon, authenticated;
grant select on public.vendor_rate_latest to authenticated;

-- >>>>>>>>>> 0028_profile_hero_image.sql
-- =============================================================================
-- 0028_profile_hero_image.sql — a landing photo for the Guest Studio.
--
-- Each user can upload their own event photo (Settings → Branding → Landing photo). It is
-- shown in the featured card on the Studio landing page; without one, a designed "golden
-- stage" is shown instead. Stored in the existing private `brand` bucket (per-user folder).
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.profiles add column if not exists hero_image_path text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_hero_image_path_len') then
    alter table public.profiles add constraint profiles_hero_image_path_len check (hero_image_path is null or length(hero_image_path) <= 300);
  end if;
end $$;

-- Users may set it on their own profile (same rule as the logo).
grant update (hero_image_path) on public.profiles to authenticated;

-- >>>>>>>>>> 0029_performer_photos.sql
-- =============================================================================
-- 0029_performer_photos.sql — "On our stage" photos for the Guest Studio landing.
--
-- Each user can upload up to 6 photos of guests/artists performing at their venue
-- (Settings → Branding → Performer photos). The landing page cycles through them.
-- Paths point into the existing private `brand` bucket (per-user folder).
-- Safe to re-run (idempotent).
-- =============================================================================

alter table public.profiles add column if not exists performer_photo_paths text[] not null default '{}';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_performer_photo_paths_max') then
    alter table public.profiles add constraint profiles_performer_photo_paths_max
      check (coalesce(array_length(performer_photo_paths, 1), 0) <= 6);
  end if;
end $$;

-- Users may set it on their own profile (same rule as the logo and landing photo).
grant update (performer_photo_paths) on public.profiles to authenticated;
